  if (pthread_mutex_lock(&maintenance->mutex) != 0) {
    maintenance->rc = LC_ERR_TRANSPORT;
    return NULL;
  }
  maintenance->started = 1;
  (void)pthread_cond_broadcast(&maintenance->cond);
  (void)pthread_mutex_unlock(&maintenance->mutex);
