static void *pouch_acquire_lease_in_parallel(void *context) {
  pouch_parallel_lease_acquire *acquire;
  lc_acquire_req request;
  lc_release_req release_request;
  int barrier_rc;
  unsigned int attempt;

  acquire = (pouch_parallel_lease_acquire *)context;
  lc_error_init(&acquire->error);
  lc_acquire_req_init(&request);
  lc_release_req_init(&release_request);
  request.key = acquire->key;
  request.owner = "parallel-owner";
  request.ttl_seconds = 30L;
  barrier_rc = pthread_barrier_wait(acquire->start);
  if (barrier_rc != 0 && barrier_rc != PTHREAD_BARRIER_SERIAL_THREAD) {
    acquire->rc = lc_error_set(&acquire->error, LC_ERR_TRANSPORT, 0L,
                               "parallel pouch acquire barrier failed", NULL,
                               NULL, "pouch");
    return NULL;
  }
  acquire->rc = LC_OK;
  for (attempt = 0U; attempt < acquire->attempts && acquire->rc == LC_OK;
       ++attempt) {
    lc_lease *lease;

    lease = NULL;
    acquire->rc = acquire->client->acquire(acquire->client, &request, &lease,
                                           &acquire->error);
    if (acquire->rc == LC_OK) {
      acquire->last_fencing_token = lease->fencing_token;
      acquire->rc = lease->release(lease, &release_request, &acquire->error);
      if (acquire->rc != LC_OK) {
        lease->close(lease);
      } else {
        ++acquire->completed;
      }
    }
  }
  return NULL;
}

static void *pouch_client_mutate_in_parallel(void *context) {
  pouch_parallel_client_mutate *mutate;
  lc_mutate_op request;
  const char *mutations[1];
  unsigned int attempt;
  int barrier_rc;

  mutate = (pouch_parallel_client_mutate *)context;
  lc_error_init(&mutate->error);
  lc_mutate_op_init(&request);
  mutations[0] = "/counter++";
  request.lease = mutate->lease;
  request.mutations = mutations;
  request.mutation_count = 1U;
  barrier_rc = pthread_barrier_wait(mutate->start);
  if (barrier_rc != 0 && barrier_rc != PTHREAD_BARRIER_SERIAL_THREAD) {
    mutate->rc = lc_error_set(&mutate->error, LC_ERR_TRANSPORT, 0L,
                              "parallel pouch mutate barrier failed", NULL,
                              NULL, "pouch");
    return NULL;
  }
  mutate->rc = LC_OK;
  for (attempt = 0U; attempt < mutate->attempts && mutate->rc == LC_OK;
       ++attempt) {
    lc_mutate_res result;

    memset(&result, 0, sizeof(result));
    mutate->rc = mutate->client->mutate(mutate->client, &request, &result,
                                        &mutate->error);
    if (mutate->rc == LC_OK) {
      ++mutate->completed;
    }
    lc_mutate_res_cleanup(&result);
  }
  return NULL;
}

