static void
test_single_writer_transition_waits_for_active_append_operation(void **state) {
  lc_pouch *pouch;
  pouch_mode_transition_context transition;
  lc_pouch_status status;
  pthread_t key_thread;
  pthread_t transition_thread;
  struct timespec deadline;
  lc_error error;
  char root[512];
  int wait_rc;
  int rc;

  (void)state;
  pouch = NULL;
  memset(&transition, 0, sizeof(transition));
  memset(&status, 0, sizeof(status));
  lc_error_init(&error);
  make_root("single-writer-transition-barrier", root, sizeof(root));
  cleanup_root(root);

  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  transition.pouch = pouch;
  assert_int_equal(pthread_mutex_init(&transition.mutex, NULL), 0);
  assert_int_equal(pthread_cond_init(&transition.cond, NULL), 0);
  assert_int_equal(pthread_create(&key_thread, NULL,
                                  pouch_mode_transition_hold_key, &transition),
                   0);
  assert_int_equal(pthread_mutex_lock(&transition.mutex), 0);
  while (!transition.key_lock_entered) {
    assert_int_equal(pthread_cond_wait(&transition.cond, &transition.mutex), 0);
  }
  assert_int_equal(pthread_mutex_unlock(&transition.mutex), 0);

  /* The active callback has pinned the old writer mode through completion. */
  assert_int_equal(pthread_rwlock_trywrlock(&pouch->writer_mode_guard), EBUSY);
  assert_int_equal(pthread_create(&transition_thread, NULL,
                                  pouch_mode_transition_change_mode,
                                  &transition),
                   0);
  assert_int_equal(pthread_mutex_lock(&transition.mutex), 0);
  while (!transition.transition_started) {
    assert_int_equal(pthread_cond_wait(&transition.cond, &transition.mutex), 0);
  }
  assert_int_equal(clock_gettime(CLOCK_REALTIME, &deadline), 0);
  deadline.tv_nsec += 100L * 1000L * 1000L;
  if (deadline.tv_nsec >= 1000000000L) {
    deadline.tv_sec += 1;
    deadline.tv_nsec -= 1000000000L;
  }
  wait_rc = 0;
  while (!transition.transition_finished && wait_rc == 0) {
    wait_rc =
        pthread_cond_timedwait(&transition.cond, &transition.mutex, &deadline);
  }
  assert_int_equal(wait_rc, ETIMEDOUT);
  assert_false(transition.transition_finished);
  transition.allow_key_lock_exit = 1;
  assert_int_equal(pthread_cond_broadcast(&transition.cond), 0);
  assert_int_equal(pthread_mutex_unlock(&transition.mutex), 0);

  assert_int_equal(pthread_join(key_thread, NULL), 0);
  assert_int_equal(pthread_join(transition_thread, NULL), 0);
  assert_int_equal(transition.key_lock_rc, LC_OK);
  assert_int_equal(transition.transition_rc, LC_OK);
  rc = lc_pouch_status_read(pouch, &status, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(status.single_writer);
  assert_true(status.supports_concurrent_writes);
  lc_pouch_status_cleanup(NULL, &status);
  lc_error_cleanup(&transition.transition_error);
  lc_error_cleanup(&transition.key_lock_error);
  assert_int_equal(pthread_cond_destroy(&transition.cond), 0);
  assert_int_equal(pthread_mutex_destroy(&transition.mutex), 0);
  lc_pouch_close(pouch);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void
test_namespace_callback_key_lock_does_not_reacquire_writer_mode(void **state) {
  lc_pouch *pouch;
  pouch_mode_transition_context transition;
  pthread_t namespace_thread;
  pthread_t transition_thread;
  struct timespec deadline;
  struct timespec transition_delay;
  int wait_rc;
  int rc;
  lc_error error;
  char root[512];

  (void)state;
  pouch = NULL;
  memset(&transition, 0, sizeof(transition));
  lc_error_init(&error);
  make_root("namespace-key-writer-mode", root, sizeof(root));
  cleanup_root(root);

  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  transition.pouch = pouch;
  assert_int_equal(pthread_mutex_init(&transition.mutex, NULL), 0);
  assert_int_equal(pthread_cond_init(&transition.cond, NULL), 0);
  assert_int_equal(pthread_create(&namespace_thread, NULL,
                                  pouch_mode_transition_hold_namespace,
                                  &transition),
                   0);
  assert_int_equal(pthread_mutex_lock(&transition.mutex), 0);
  while (!transition.key_lock_entered) {
    assert_int_equal(pthread_cond_wait(&transition.cond, &transition.mutex), 0);
  }
  assert_int_equal(pthread_mutex_unlock(&transition.mutex), 0);

  assert_int_equal(pthread_create(&transition_thread, NULL,
                                  pouch_mode_transition_change_mode,
                                  &transition),
                   0);
  assert_int_equal(pthread_mutex_lock(&transition.mutex), 0);
  while (!transition.transition_started) {
    assert_int_equal(pthread_cond_wait(&transition.cond, &transition.mutex), 0);
  }
  assert_int_equal(pthread_mutex_unlock(&transition.mutex), 0);
  transition_delay.tv_sec = 0;
  transition_delay.tv_nsec = 20L * 1000L * 1000L;
  assert_int_equal(nanosleep(&transition_delay, NULL), 0);

  assert_int_equal(pthread_mutex_lock(&transition.mutex), 0);
  transition.allow_key_lock_exit = 1;
  assert_int_equal(pthread_cond_broadcast(&transition.cond), 0);
  assert_int_equal(clock_gettime(CLOCK_REALTIME, &deadline), 0);
  deadline.tv_sec += 1;
  wait_rc = 0;
  while (!transition.operation_finished && wait_rc == 0) {
    wait_rc =
        pthread_cond_timedwait(&transition.cond, &transition.mutex, &deadline);
  }
  assert_int_equal(wait_rc, 0);
  assert_true(transition.operation_finished);
  assert_int_equal(pthread_mutex_unlock(&transition.mutex), 0);

  assert_int_equal(pthread_join(namespace_thread, NULL), 0);
  assert_int_equal(pthread_join(transition_thread, NULL), 0);
  assert_int_equal(transition.namespace_lock_rc, LC_OK);
  assert_int_equal(transition.transition_rc, LC_OK);
  lc_error_cleanup(&transition.namespace_lock_error);
  lc_error_cleanup(&transition.transition_error);
  assert_int_equal(pthread_cond_destroy(&transition.cond), 0);
  assert_int_equal(pthread_mutex_destroy(&transition.mutex), 0);
  lc_pouch_close(pouch);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_maintenance_waits_for_active_key_operation(void **state) {
  lc_pouch *pouch;
  pouch_mode_transition_context key_operation;
  pouch_maintenance_barrier_context maintenance;
  pthread_t key_thread;
  pthread_t maintenance_thread;
  struct timespec deadline;
  lc_error error;
  char root[512];
  int wait_rc;
  int rc;

  (void)state;
  pouch = NULL;
  memset(&key_operation, 0, sizeof(key_operation));
  memset(&maintenance, 0, sizeof(maintenance));
  lc_error_init(&error);
  make_root("maintenance-key-barrier", root, sizeof(root));
  cleanup_root(root);

  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  key_operation.pouch = pouch;
  maintenance.pouch = pouch;
  assert_int_equal(pthread_mutex_init(&key_operation.mutex, NULL), 0);
  assert_int_equal(pthread_cond_init(&key_operation.cond, NULL), 0);
  assert_int_equal(pthread_mutex_init(&maintenance.mutex, NULL), 0);
  assert_int_equal(pthread_cond_init(&maintenance.cond, NULL), 0);
  assert_int_equal(pthread_create(&key_thread, NULL,
                                  pouch_mode_transition_hold_key,
                                  &key_operation),
                   0);
  assert_int_equal(pthread_mutex_lock(&key_operation.mutex), 0);
  while (!key_operation.key_lock_entered) {
    assert_int_equal(
        pthread_cond_wait(&key_operation.cond, &key_operation.mutex), 0);
  }
  assert_int_equal(pthread_mutex_unlock(&key_operation.mutex), 0);
  assert_int_equal(pthread_create(&maintenance_thread, NULL,
                                  pouch_maintenance_wait_for_key, &maintenance),
                   0);
  assert_int_equal(pthread_mutex_lock(&maintenance.mutex), 0);
  while (!maintenance.started) {
    assert_int_equal(pthread_cond_wait(&maintenance.cond, &maintenance.mutex),
                     0);
  }
  assert_int_equal(clock_gettime(CLOCK_REALTIME, &deadline), 0);
  deadline.tv_nsec += 100L * 1000L * 1000L;
  if (deadline.tv_nsec >= 1000000000L) {
    deadline.tv_sec += 1;
    deadline.tv_nsec -= 1000000000L;
  }
  wait_rc = 0;
  while (!maintenance.finished && wait_rc == 0) {
    wait_rc = pthread_cond_timedwait(&maintenance.cond, &maintenance.mutex,
                                     &deadline);
  }
  assert_int_equal(wait_rc, ETIMEDOUT);
  assert_false(maintenance.finished);
  assert_int_equal(pthread_mutex_unlock(&maintenance.mutex), 0);
  assert_int_equal(pthread_mutex_lock(&key_operation.mutex), 0);
  key_operation.allow_key_lock_exit = 1;
  assert_int_equal(pthread_cond_broadcast(&key_operation.cond), 0);
  assert_int_equal(pthread_mutex_unlock(&key_operation.mutex), 0);
  assert_int_equal(pthread_join(key_thread, NULL), 0);
  assert_int_equal(pthread_join(maintenance_thread, NULL), 0);
  assert_int_equal(key_operation.key_lock_rc, LC_OK);
  assert_int_equal(maintenance.rc, LC_OK);
  lc_error_cleanup(&maintenance.error);
  lc_error_cleanup(&key_operation.key_lock_error);
  assert_int_equal(pthread_cond_destroy(&maintenance.cond), 0);
  assert_int_equal(pthread_mutex_destroy(&maintenance.mutex), 0);
  assert_int_equal(pthread_cond_destroy(&key_operation.cond), 0);
  assert_int_equal(pthread_mutex_destroy(&key_operation.mutex), 0);
  lc_pouch_close(pouch);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_pouch_disk_runtime_controls(void **state) {
  lc_pouch *writer;
  lc_pouch *peer;
  lc_pouch_open_options options;
  lc_pouch_status status;
  lc_pouch_fsync_stats fsync_stats;
  lc_pouch_state_write_result write_result;
  lc_source *source;
  lc_error error;
  char root[512];
  char backend_hash[LC_POUCH_BACKEND_HASH_HEX_BYTES + 1U];
  char repeated_backend_hash[LC_POUCH_BACKEND_HASH_HEX_BYTES + 1U];
  int queue_watch_enabled;
  int rc;

  (void)state;
  writer = NULL;
  peer = NULL;
  source = NULL;
  memset(&options, 0, sizeof(options));
  memset(&status, 0, sizeof(status));
  memset(&fsync_stats, 0, sizeof(fsync_stats));
  memset(&write_result, 0, sizeof(write_result));
  lc_error_init(&error);
  make_root("disk-runtime-controls", root, sizeof(root));
  cleanup_root(root);

  options.single_writer_set = 1;
  options.single_writer = 1;
  options.fsync_batch_max_ops = 1U;
  options.queue_watch = 1;
  rc = lc_pouch_open(root, NULL, &options, &writer, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(lc_pouch_supports_concurrent_writes(writer));

  rc = lc_pouch_status_read(writer, &status, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(status.single_writer);
  assert_false(status.supports_concurrent_writes);
  assert_false(status.durable_sync);
  assert_int_equal(status.fsync_batch_max_ops, 1U);
  queue_watch_enabled = status.queue_watch_enabled;
  assert_non_null(status.queue_watch_mode);
  assert_non_null(status.queue_watch_reason);
  if (status.queue_watch_enabled) {
    assert_string_equal(status.queue_watch_mode, "fsnotify");
    assert_string_equal(status.queue_watch_reason, "filesystem_watch_enabled");
  } else {
    assert_string_equal(status.queue_watch_mode, "polling");
  }
  lc_pouch_status_cleanup(NULL, &status);

#if defined(__linux__)
  if (queue_watch_enabled) {
    char *namespace_path;
    char *notify_dir;
    char *notify_path;
    pouch_queue_notification_write write;
    pthread_t writer_thread;

    rc = lc_pouch_namespace_ensure_layout(NULL, root, "default", &error);
    assert_int_equal(rc, LC_OK);
    namespace_path = lc_pouch_namespace_path(NULL, root, "default");
    assert_non_null(namespace_path);
    notify_dir = lc_pouch_path_join(NULL, namespace_path, "queue-notify");
    notify_path = lc_pouch_path_join(NULL, notify_dir, "jobs.notify");
    assert_non_null(notify_dir);
    assert_non_null(notify_path);
    memset(&write, 0, sizeof(write));
    write.path = notify_path;
    write.delay.tv_sec = 0;
    write.delay.tv_nsec = 20L * 1000L * 1000L;
    assert_int_equal(pthread_create(&writer_thread, NULL,
                                    pouch_write_queue_notification, &write),
                     0);
    assert_int_equal(
        lc_pouch_queue_watch_wait(writer, "default", "jobs", 1000U), 1);
    assert_int_equal(pthread_join(writer_thread, NULL), 0);
    assert_int_equal(write.rc, LC_OK);
    lc_free_with_allocator(NULL, notify_path);
    lc_free_with_allocator(NULL, notify_dir);
    lc_free_with_allocator(NULL, namespace_path);
  }
#else
  (void)queue_watch_enabled;
#endif

  rc = lc_pouch_backend_hash(writer, backend_hash, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_backend_hash(writer, repeated_backend_hash, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(strlen(backend_hash), LC_POUCH_BACKEND_HASH_HEX_BYTES);
  assert_string_equal(backend_hash, repeated_backend_hash);

  rc = lc_source_from_memory("runtime-controls", strlen("runtime-controls"),
                             &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(writer, "default", "runtime-controls/key", source,
                            NULL, &write_result, &error);
  assert_int_equal(rc, LC_OK);
  lc_source_close(source);
  source = NULL;
  rc = lc_pouch_fsync_stats_read(writer, &fsync_stats, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(fsync_stats.total_batches, 0U);
  assert_int_equal(fsync_stats.total_requests, 0U);
  assert_int_equal(fsync_stats.max_batch_size, 0U);
  assert_int_equal(fsync_stats.bounds[0], 1U);
  assert_int_equal(fsync_stats.bounds[LC_POUCH_FSYNC_BATCH_BOUND_COUNT - 1U],
                   4096U);
  lc_pouch_state_write_result_cleanup(NULL, &write_result);

  rc = lc_pouch_abort(writer, &error);
  assert_int_equal(rc, LC_OK);
  assert_null(writer->namespace_logstores);
  assert_null(writer->source_cache_entries);
  lc_error_cleanup(&error);
  lc_error_init(&error);
  rc = lc_source_from_memory("after-abort", strlen("after-abort"), &source,
                             &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(writer, "default", "runtime-controls/after-abort",
                            source, NULL, &write_result, &error);
  assert_int_equal(rc, LC_ERR_INVALID);
  lc_source_close(source);
  source = NULL;
  lc_error_cleanup(&error);
  lc_error_init(&error);
  rc = lc_pouch_status_read(writer, &status, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(status.aborted);
  lc_pouch_status_cleanup(NULL, &status);
  lc_pouch_close(writer);
  writer = NULL;
  rc = lc_pouch_open(root, NULL, NULL, &peer, &error);
  assert_int_equal(rc, LC_ERR_INVALID);
  assert_null(peer);
  assert_string_equal(error.message,
                      "pouch root has an unexpired exclusive writer");
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void
test_resident_descriptors_stay_bounded_across_lifecycle(void **state) {
  lc_pouch *pouch;
  lc_pouch_open_options options;
  lc_pouch_maintenance_options maintenance_options;
  lc_pouch_maintenance_result maintenance_result;
  lc_pouch_state_write_result write_result;
  lc_source *source;
  lc_error error;
  char root[512];
  int rc;

  (void)state;
  pouch = NULL;
  source = NULL;
  memset(&options, 0, sizeof(options));
  memset(&maintenance_options, 0, sizeof(maintenance_options));
  memset(&maintenance_result, 0, sizeof(maintenance_result));
  memset(&write_result, 0, sizeof(write_result));
  lc_error_init(&error);
  make_root("resident-descriptor-lifecycle", root, sizeof(root));
  cleanup_root(root);

  options.segment_target_bytes = 1U;
  rc = lc_pouch_open(root, NULL, &options, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_source_from_memory("first", strlen("first"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(pouch, "default", "state/first", source, NULL,
                            &write_result, &error);
  assert_int_equal(rc, LC_OK);
  lc_source_close(source);
  source = NULL;
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  assert_int_equal(lc_pouch_test_resident_descriptor_count(pouch), 1U);

  rc = lc_source_from_memory("second", strlen("second"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(pouch, "default", "state/second", source, NULL,
                            &write_result, &error);
  assert_int_equal(rc, LC_OK);
  lc_source_close(source);
  source = NULL;
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  assert_int_equal(lc_pouch_test_resident_descriptor_count(pouch), 1U);

  maintenance_options.namespace_name = "default";
  maintenance_options.force = 1;
  rc = lc_pouch_maintenance_run(pouch, &maintenance_options,
                                &maintenance_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(maintenance_result.compacted);
  lc_pouch_maintenance_result_cleanup(NULL, &maintenance_result);
  assert_true(lc_pouch_test_resident_descriptor_count(pouch) <= 1U);

  rc = lc_source_from_memory("handoff", strlen("handoff"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(pouch, "default", "state/handoff", source, NULL,
                            &write_result, &error);
  assert_int_equal(rc, LC_OK);
  lc_source_close(source);
  source = NULL;
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  assert_int_equal(lc_pouch_test_resident_descriptor_count(pouch), 1U);

  rc = lc_pouch_set_single_writer(pouch, 0, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(lc_pouch_test_resident_descriptor_count(pouch) <= 1U);
  rc = lc_source_from_memory("shared", strlen("shared"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(pouch, "default", "state/shared", source, NULL,
                            &write_result, &error);
  assert_int_equal(rc, LC_OK);
  lc_source_close(source);
  source = NULL;
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  assert_int_equal(lc_pouch_test_resident_descriptor_count(pouch), 0U);
  rc = lc_pouch_set_single_writer(pouch, 1, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(lc_pouch_test_resident_descriptor_count(pouch), 0U);

  rc = lc_source_from_memory("third", strlen("third"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(pouch, "default", "state/third", source, NULL,
                            &write_result, &error);
  assert_int_equal(rc, LC_OK);
  lc_source_close(source);
  source = NULL;
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  assert_int_equal(lc_pouch_test_resident_descriptor_count(pouch), 1U);

  rc = lc_pouch_abort(pouch, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(lc_pouch_test_resident_descriptor_count(pouch), 0U);

  lc_pouch_close(pouch);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_pouch_durable_sync_policy(void **state) {
  lc_pouch *pouch;
  lc_pouch_open_options options;
  lc_pouch_status status;
  lc_pouch_fsync_stats fsync_stats;
  lc_pouch_state_write_result write_result;
  lc_source *source;
  lc_error error;
  char root[512];
  int rc;

  (void)state;
  pouch = NULL;
  source = NULL;
  memset(&options, 0, sizeof(options));
  memset(&status, 0, sizeof(status));
  memset(&fsync_stats, 0, sizeof(fsync_stats));
  memset(&write_result, 0, sizeof(write_result));
  lc_error_init(&error);
  make_root("durable-sync-policy", root, sizeof(root));
  cleanup_root(root);

  options.durable_sync = 1;
  options.fsync_batch_max_ops = 1U;
  rc = lc_pouch_open(root, NULL, &options, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_status_read(pouch, &status, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(status.durable_sync);
  assert_int_equal(status.fsync_batch_max_ops, 1U);
  lc_pouch_status_cleanup(NULL, &status);

  rc = lc_source_from_memory("durable", strlen("durable"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(pouch, "default", "durable-sync/key", source, NULL,
                            &write_result, &error);
  assert_int_equal(rc, LC_OK);
  lc_source_close(source);
  source = NULL;
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  rc = lc_pouch_fsync_stats_read(pouch, &fsync_stats, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(fsync_stats.total_batches > 0U);
  assert_true(fsync_stats.total_requests > 0U);
  assert_int_equal(fsync_stats.max_batch_size, 1U);
  assert_int_equal(fsync_stats.bounds[0], 1U);
  assert_int_equal(fsync_stats.bounds[LC_POUCH_FSYNC_BATCH_BOUND_COUNT - 1U],
                   4096U);

  lc_pouch_close(pouch);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_pouch_durable_sync_batches_parallel_writes(void **state) {
  lc_pouch *pouch;
  lc_pouch_open_options options;
  lc_pouch_fsync_stats fsync_stats;
  pouch_parallel_fsync_commit commits[4];
  pthread_barrier_t start;
  pthread_t threads[4];
  lc_error error;
  char root[512];
  char fsync_path[1024];
  int fd;
  size_t index;
  int rc;

  (void)state;
  pouch = NULL;
  fd = -1;
  memset(&options, 0, sizeof(options));
  memset(&fsync_stats, 0, sizeof(fsync_stats));
  memset(commits, 0, sizeof(commits));
  lc_error_init(&error);
  make_root("durable-sync-batch", root, sizeof(root));
  cleanup_root(root);

  options.durable_sync = 1;
  options.fsync_batch_max_ops = 4U;
  rc = lc_pouch_open(root, NULL, &options, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(
      snprintf(fsync_path, sizeof(fsync_path), "%s/fsync-batch.log", root) > 0);
  fd = open(fsync_path, O_CREAT | O_RDWR | O_TRUNC, 0600);
  assert_true(fd >= 0);
  assert_int_equal(write(fd, "x", 1U), 1);
  assert_int_equal(pthread_barrier_init(&start, NULL, 4U), 0);
  lc_pouch_test_fsync_batch_delay_ns = 50000000L;
  for (index = 0U; index < 4U; ++index) {
    commits[index].pouch = pouch;
    commits[index].start = &start;
    commits[index].fd = fd;
    assert_int_equal(pthread_create(&threads[index], NULL,
                                    pouch_fsync_commit_in_parallel,
                                    &commits[index]),
                     0);
  }
  for (index = 0U; index < 4U; ++index) {
    assert_int_equal(pthread_join(threads[index], NULL), 0);
  }
  lc_pouch_test_fsync_batch_delay_ns = 0L;
  assert_int_equal(pthread_barrier_destroy(&start), 0);
  for (index = 0U; index < 4U; ++index) {
    assert_int_equal(commits[index].rc, LC_OK);
    lc_error_cleanup(&commits[index].error);
  }
  rc = lc_pouch_fsync_stats_read(pouch, &fsync_stats, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(fsync_stats.total_requests, 4U);
  assert_true(fsync_stats.total_batches < fsync_stats.total_requests);
  assert_true(fsync_stats.max_batch_size > 1U);

  assert_int_equal(close(fd), 0);
  lc_pouch_close(pouch);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

