  assert_int_equal(rc, LC_OK);
  assert_int_equal(state_index_seq, 1UL);
  assert_int_equal(pthread_barrier_init(&start, NULL, 2U), 0);
  write.pouch = pouch;
  write.start = &start;
  write.key = "query-flush/later";
  write.value = "{\"value\":2}";
