static void test_shared_clients_dequeue_one_message_once(void **state) {
  lc_client *first_client;
  lc_client *second_client;
  lc_source *source;
  lc_enqueue_req enqueue_req;
  lc_enqueue_res enqueue_res;
  pouch_parallel_queue_dequeue first_dequeue;
  pouch_parallel_queue_dequeue second_dequeue;
  pthread_barrier_t start;
  pthread_t first_thread;
  pthread_t second_thread;
  lc_error error;
  char root[512];
  int rc;

  (void)state;
  first_client = NULL;
  second_client = NULL;
  source = NULL;
  memset(&enqueue_res, 0, sizeof(enqueue_res));
  memset(&first_dequeue, 0, sizeof(first_dequeue));
  memset(&second_dequeue, 0, sizeof(second_dequeue));
  lc_enqueue_req_init(&enqueue_req);
  lc_error_init(&error);
  make_root("shared-queue-delivery", root, sizeof(root));
  cleanup_root(root);

  open_pouch_client_shared(root, &first_client, &error);
  open_pouch_client_shared(root, &second_client, &error);
  enqueue_req.queue = "jobs";
  enqueue_req.content_type = "text/plain";
  enqueue_req.visibility_timeout_seconds = 60L;
  rc = lc_source_from_memory("job", strlen("job"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = first_client->enqueue(first_client, &enqueue_req, source, &enqueue_res,
                             &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);

  assert_int_equal(pthread_barrier_init(&start, NULL, 2U), 0);
  first_dequeue.client = first_client;
  first_dequeue.start = &start;
  first_dequeue.owner = "first-worker";
  second_dequeue.client = second_client;
  second_dequeue.start = &start;
  second_dequeue.owner = "second-worker";
  assert_int_equal(pthread_create(&first_thread, NULL,
                                  pouch_dequeue_queue_message_in_parallel,
                                  &first_dequeue),
                   0);
  assert_int_equal(pthread_create(&second_thread, NULL,
                                  pouch_dequeue_queue_message_in_parallel,
                                  &second_dequeue),
                   0);
  assert_int_equal(pthread_join(first_thread, NULL), 0);
  assert_int_equal(pthread_join(second_thread, NULL), 0);
  assert_int_equal(pthread_barrier_destroy(&start), 0);
  assert_int_equal(first_dequeue.rc, LC_OK);
  assert_int_equal(second_dequeue.rc, LC_OK);
  assert_true((first_dequeue.message != NULL) !=
              (second_dequeue.message != NULL));

  if (first_dequeue.message != NULL) {
    first_dequeue.message->close(first_dequeue.message);
  }
  if (second_dequeue.message != NULL) {
    second_dequeue.message->close(second_dequeue.message);
  }
  lc_error_cleanup(&second_dequeue.error);
  lc_error_cleanup(&first_dequeue.error);
  lc_enqueue_res_cleanup(&enqueue_res);
  lc_client_close(second_client);
  lc_client_close(first_client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

/* These helpers intentionally open Pouch only after fork. The parent test
 * never has a live Pouch worker while it forks, so this validates real
 * cross-process locks without re-entering a threaded client in a child. */
static int pouch_shared_process_write_with_segment_target(
    const char *root, const char *key, const char *value, int start_fd,
    uint64_t segment_target_bytes);
static int pouch_shared_process_write_many_with_segment_target(
    const char *root, const char *prefix, int ready_fd, int start_fd,
    uint64_t segment_target_bytes, uint64_t count);

static int pouch_shared_process_write_with_segment_target(
    const char *root, const char *key, const char *value, int start_fd,
    uint64_t segment_target_bytes) {
  lc_pouch *pouch;
  lc_pouch_open_options options;
  lc_pouch_state_write_result write_result;
  lc_source *source;
  lc_error error;
  char start;
  int rc;

  pouch = NULL;
  source = NULL;
  memset(&options, 0, sizeof(options));
  memset(&write_result, 0, sizeof(write_result));
  lc_error_init(&error);
  rc = read(start_fd, &start, 1U) == 1 ? LC_OK : LC_ERR_TRANSPORT;
  (void)close(start_fd);
  options.single_writer_set = 1;
  options.single_writer = 0;
  options.segment_target_bytes = segment_target_bytes;
  if (rc == LC_OK) {
    rc = lc_pouch_open(root, NULL, &options, &pouch, &error);
  }
  if (rc == LC_OK) {
    rc = lc_source_from_memory(value, strlen(value), &source, &error);
  }
  if (rc == LC_OK) {
    rc = lc_pouch_state_write(pouch, "default", key, source, NULL,
                              &write_result, &error);
  }
  if (source != NULL) {
    lc_source_close(source);
  }
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  if (pouch != NULL) {
    lc_pouch_close(pouch);
  }
  lc_error_cleanup(&error);
  return rc;
}

/* Keep both independent Pouch projections warm while they append to the same
 * active segment. A shared reader must tail only completed peer records; a
 * transient append must never surface as record corruption. */
static int pouch_shared_process_write_many_with_segment_target(
    const char *root, const char *prefix, int ready_fd, int start_fd,
    uint64_t segment_target_bytes, uint64_t count) {
  lc_pouch *pouch;
  lc_pouch_open_options options;
  lc_error error;
  char start;
  char seed_key[128];
  uint64_t index;
  int rc;

  pouch = NULL;
  memset(&options, 0, sizeof(options));
  lc_error_init(&error);
  if (count == 0U || count > POUCH_SHARED_ACTIVE_TAIL_WRITES) {
    rc = LC_ERR_INVALID;
  } else {
    rc = LC_OK;
  }
  options.single_writer_set = 1;
  options.single_writer = 0;
  options.segment_target_bytes = segment_target_bytes;
  if (rc == LC_OK) {
    rc = lc_pouch_open(root, NULL, &options, &pouch, &error);
  }
  if (rc == LC_OK) {
    lc_pouch_state_write_result write_result;
    lc_source *source;
    int written;

    memset(&write_result, 0, sizeof(write_result));
    source = NULL;
    written = snprintf(seed_key, sizeof(seed_key),
                       "state/process-active-tail/%s/seed", prefix);
    if (written < 0 || (size_t)written >= sizeof(seed_key)) {
      rc = LC_ERR_INVALID;
    }
    if (rc == LC_OK) {
      rc = lc_source_from_memory(prefix, strlen(prefix), &source, &error);
    }
    if (rc == LC_OK) {
      rc = lc_pouch_state_write(pouch, "default", seed_key, source, NULL,
                                &write_result, &error);
    }
    if (source != NULL) {
      lc_source_close(source);
    }
    lc_pouch_state_write_result_cleanup(NULL, &write_result);
  }
  if (rc == LC_OK && write(ready_fd, "1", 1U) != 1) {
    rc = LC_ERR_TRANSPORT;
  }
  if (rc == LC_OK && read(start_fd, &start, 1U) != 1) {
    rc = LC_ERR_TRANSPORT;
  }
  (void)close(ready_fd);
  (void)close(start_fd);
  for (index = 0U; rc == LC_OK && index < count; ++index) {
    lc_pouch_state_write_result write_result;
    lc_source *source;
    char key[128];
    char label[64];
    char value[768];
    int written;

    memset(&write_result, 0, sizeof(write_result));
    source = NULL;
    written = snprintf(key, sizeof(key), "state/process-active-tail/%s/%03lu",
                       prefix, (unsigned long)index);
    if (written < 0 || (size_t)written >= sizeof(key)) {
      rc = LC_ERR_INVALID;
    }
    if (rc == LC_OK) {
      memset(value, (int)prefix[0], sizeof(value) - 1U);
      value[sizeof(value) - 1U] = '\0';
      written = snprintf(label, sizeof(label), "%s-%03lu", prefix,
                         (unsigned long)index);
      if (written < 0 || (size_t)written >= sizeof(label)) {
        rc = LC_ERR_INVALID;
      } else {
        memcpy(value, label, (size_t)written);
      }
    }
    if (rc == LC_OK) {
      rc = lc_source_from_memory(value, sizeof(value) - 1U, &source, &error);
    }
    if (rc == LC_OK) {
      rc = lc_pouch_state_write(pouch, "default", key, source, NULL,
                                &write_result, &error);
    }
    if (source != NULL) {
      lc_source_close(source);
    }
    lc_pouch_state_write_result_cleanup(NULL, &write_result);
  }
  if (pouch != NULL) {
    lc_pouch_close(pouch);
  }
  lc_error_cleanup(&error);
  return rc;
}

static int pouch_exclusive_process_hold(const char *root, int ready_fd,
                                        int release_fd) {
  lc_pouch *pouch;
  lc_error error;
  char signal;
  int rc;

  pouch = NULL;
  lc_error_init(&error);
  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  if (rc == LC_OK && write(ready_fd, "1", 1U) != 1) {
    rc = LC_ERR_TRANSPORT;
  }
  if (rc == LC_OK && read(release_fd, &signal, 1U) != 1) {
    rc = LC_ERR_TRANSPORT;
  }
  (void)close(ready_fd);
  (void)close(release_fd);
  if (pouch != NULL) {
    lc_pouch_close(pouch);
  }
  lc_error_cleanup(&error);
  return rc;
}

