static int pouch_shared_process_dequeue(const char *root, const char *owner,
                                        int ready_fd, int start_fd,
                                        int result_fd) {
  lc_client *client;
  lc_message *message;
  lc_dequeue_req request;
  lc_error error;
  char signal;
  char delivered;
  int rc;

  client = NULL;
  message = NULL;
  lc_dequeue_req_init(&request);
  lc_error_init(&error);
  request.queue = "jobs";
  request.owner = owner;
  request.visibility_timeout_seconds = 60L;
  rc = pouch_shared_process_open_client(root, &client, &error);
  if (rc == LC_OK && write(ready_fd, "1", 1U) != 1) {
    rc = LC_ERR_TRANSPORT;
  }
  if (rc == LC_OK && read(start_fd, &signal, 1U) != 1) {
    rc = LC_ERR_TRANSPORT;
  }
  if (rc == LC_OK) {
    rc = client->dequeue(client, &request, &message, &error);
  }
  delivered = message != NULL ? '1' : '0';
  if (rc == LC_OK && write(result_fd, &delivered, 1U) != 1) {
    rc = LC_ERR_TRANSPORT;
  }
  (void)close(ready_fd);
  (void)close(start_fd);
  (void)close(result_fd);
  if (message != NULL) {
    message->close(message);
  }
  if (client != NULL) {
    lc_client_close(client);
  }
  lc_error_cleanup(&error);
  return rc;
}

static int pouch_shared_process_stage_write(const char *root, const char *key,
                                            const char *value,
                                            const char *txn_id, int start_fd) {
  lc_pouch *pouch;
  lc_pouch_open_options options;
  lc_pouch_state_write_result write_result;
  lc_source *source;
  lc_error error;
  char start;
  int rc;

  pouch = NULL;
  source = NULL;
  memset(&options, 0, sizeof(options));
  memset(&write_result, 0, sizeof(write_result));
  lc_error_init(&error);
  txn_id = test_xid_for_label(txn_id);
  rc = read(start_fd, &start, 1U) == 1 ? LC_OK : LC_ERR_TRANSPORT;
  (void)close(start_fd);
  options.single_writer_set = 1;
  options.single_writer = 0;
  if (rc == LC_OK) {
    rc = lc_pouch_open(root, NULL, &options, &pouch, &error);
  }
  if (rc == LC_OK) {
    rc = lc_source_from_memory(value, strlen(value), &source, &error);
  }
  if (rc == LC_OK) {
    rc = lc_pouch_state_stage_write(pouch, "default", key, txn_id, source, NULL,
                                    &write_result, &error);
  }
  if (source != NULL) {
    lc_source_close(source);
  }
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  if (pouch != NULL) {
    lc_pouch_close(pouch);
  }
  lc_error_cleanup(&error);
  return rc;
}

static int pouch_shared_process_commit_transaction(const char *root,
                                                   const char *txn_id) {
  lc_client *client;
  lc_txn_participant participants[2];
  lc_txn_decision_req request;
  lc_txn_decision_res result;
  lc_error error;
  int rc;

  client = NULL;
  memset(participants, 0, sizeof(participants));
  lc_txn_decision_req_init(&request);
  memset(&result, 0, sizeof(result));
  lc_error_init(&error);
  txn_id = test_xid_for_label(txn_id);
  participants[0].namespace_name = "default";
  participants[0].key = "state/process-txn-first";
  participants[1].namespace_name = "default";
  participants[1].key = "state/process-txn-second";
  request.txn_id = txn_id;
  request.participants = participants;
  request.participant_count = 2U;
  rc = pouch_shared_process_open_client(root, &client, &error);
  if (rc == LC_OK) {
    rc = client->txn_commit(client, &request, &result, &error);
  }
  lc_txn_decision_res_cleanup(&result);
  if (client != NULL) {
    lc_client_close(client);
  }
  lc_error_cleanup(&error);
  return rc;
}

static int pouch_shared_process_compact_after_snapshot(const char *root,
                                                       int ready_fd,
                                                       int resume_fd) {
  lc_pouch *pouch;
  lc_pouch_open_options open_options;
  lc_pouch_maintenance_options maintenance_options;
  lc_pouch_maintenance_result maintenance_result;
  pouch_compaction_process_hook_state hook_state;
  lc_error error;
  int rc;

  pouch = NULL;
  memset(&open_options, 0, sizeof(open_options));
  memset(&maintenance_options, 0, sizeof(maintenance_options));
  memset(&maintenance_result, 0, sizeof(maintenance_result));
  memset(&hook_state, 0, sizeof(hook_state));
  lc_error_init(&error);
  open_options.single_writer_set = 1;
  open_options.single_writer = 0;
  open_options.segment_target_bytes = 512U;
  open_options.background_compaction_enabled_set = 1;
  open_options.background_compaction_enabled = 0;
  rc = lc_pouch_open(root, NULL, &open_options, &pouch, &error);
  hook_state.ready_fd = ready_fd;
  hook_state.resume_fd = resume_fd;
  if (rc == LC_OK) {
    lc_pouch_test_after_snapshot_write_hook =
        pouch_compaction_process_wait_hook;
    lc_pouch_test_after_snapshot_write_context = &hook_state;
    maintenance_options.namespace_name = "default";
    maintenance_options.force = 1;
    rc = lc_pouch_maintenance_run(pouch, &maintenance_options,
                                  &maintenance_result, &error);
    lc_pouch_test_after_snapshot_write_hook = NULL;
    lc_pouch_test_after_snapshot_write_context = NULL;
  }
  if (rc == LC_OK && !maintenance_result.compacted) {
    rc = LC_ERR_INVALID;
  }
  (void)close(ready_fd);
  (void)close(resume_fd);
  lc_pouch_maintenance_result_cleanup(NULL, &maintenance_result);
  if (pouch != NULL) {
    lc_pouch_close(pouch);
  }
  lc_error_cleanup(&error);
  return rc;
}

