static void
test_exclusive_indexer_defers_lease_metadata_until_release(void **state) {
  lc_client *client;
  lc_client_handle *handle;
  lc_lease *lease;
  lc_update_res update_res;
  lc_metadata_op metadata_op;
  lc_metadata_res metadata_res;
  lc_index_flush_req flush_req;
  lc_index_flush_res flush_res;
  lc_acquire_req acquire_req;
  lc_pouch_generation manifest_seq;
  lc_pouch_generation query_seq;
  lc_error error;
  char endpoint[1024];
  char root[512];
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  memset(&update_res, 0, sizeof(update_res));
  lc_metadata_op_init(&metadata_op);
  memset(&metadata_res, 0, sizeof(metadata_res));
  lc_index_flush_req_init(&flush_req);
  memset(&flush_res, 0, sizeof(flush_res));
  lc_acquire_req_init(&acquire_req);
  manifest_seq = 0UL;
  query_seq = 0UL;
  lc_error_init(&error);
  make_root("indexer-lease-metadata-boundary", root, sizeof(root));
  cleanup_root(root);
  assert_true(snprintf(endpoint, sizeof(endpoint),
                       "pouch://%s?indexer_flush_docs=64&"
                       "indexer_flush_interval_seconds=1",
                       root) > 0);

  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;
  write_client_state(client, "doc/lease-metadata", "{\"kind\":\"visible\"}",
                     NULL, 0L, 0, &update_res, &error);
  lc_update_res_cleanup(&update_res);
  flush_req.mode = "wait";
  rc = client->flush_index(client, &flush_req, &flush_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_index_flush_res_cleanup(&flush_res);

  acquire_req.key = "doc/lease-metadata";
  acquire_req.owner = "pouch-indexer-lease-metadata";
  acquire_req.ttl_seconds = 30L;
  rc = client->acquire(client, &acquire_req, &lease, &error);
  assert_int_equal(rc, LC_OK);
  assert_non_null(lease);

  pouch_copy_lease_ref(&metadata_op.lease, lease);
  metadata_op.has_query_hidden = 1;
  metadata_op.query_hidden = 1;
  rc = client->metadata(client, &metadata_op, &metadata_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_metadata_res_cleanup(&metadata_res);

  /* The query-hidden mutation remains private until the lease completes. A
   * later ordinary write makes the deferred publication boundary observable. */
  write_client_state(client, "doc/lease-metadata-trigger",
                     "{\"kind\":\"trigger\"}", NULL, 0L, 0, &update_res,
                     &error);
  lc_update_res_cleanup(&update_res);

  sleep(2U);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  assert_true(query_seq != 0UL);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(manifest_seq < query_seq);

  rc = lease->release(lease, NULL, &error);
  assert_int_equal(rc, LC_OK);
  lease = NULL;
  sleep(2U);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);
  assert_false(lc_pouch_query_index_has_pending(handle->pouch, "default"));

  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_query_index_sequence_ignores_lease_metadata(void **state) {
  lc_client *client;
  lc_client_handle *handle;
  lc_update_res first;
  lc_update_res second;
  lc_pouch_maintenance_options maintenance_options;
  lc_pouch_maintenance_result maintenance_result;
  lc_index_flush_req flush_req;
  lc_index_flush_res flush_res;
  lc_pouch_generation manifest_seq;
  lc_pouch_generation query_seq;
  lc_pouch_generation state_seq;
  lc_error error;
  char endpoint[1024];
  char root[512];
  int rc;

  (void)state;
  client = NULL;
  memset(&first, 0, sizeof(first));
  memset(&second, 0, sizeof(second));
  memset(&maintenance_options, 0, sizeof(maintenance_options));
  memset(&maintenance_result, 0, sizeof(maintenance_result));
  lc_index_flush_req_init(&flush_req);
  memset(&flush_res, 0, sizeof(flush_res));
  manifest_seq = 0UL;
  query_seq = 0UL;
  state_seq = 0UL;
  lc_error_init(&error);
  make_root("query-index-lease-metadata", root, sizeof(root));
  cleanup_root(root);
  assert_true(snprintf(endpoint, sizeof(endpoint),
                       "pouch://%s?segment_target_bytes=1&"
                       "indexer_flush_docs=2&"
                       "indexer_flush_interval_seconds=3600",
                       root) > 0);

  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;
  write_client_state(client, "doc/one", "{\"kind\":\"first\"}", NULL, 0L, 0,
                     &first, &error);
  write_client_state(client, "doc/two", "{\"kind\":\"second\"}", NULL, 0L, 0,
                     &second, &error);

  rc = lc_pouch_state_index_seq(handle->pouch, "default", &state_seq, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(state_seq > query_seq);
  assert_int_equal(manifest_seq, query_seq);

  maintenance_options.namespace_name = "default";
  maintenance_options.force = 1;
  rc = lc_pouch_maintenance_run(handle->pouch, &maintenance_options,
                                &maintenance_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(maintenance_result.compacted);
  lc_pouch_maintenance_result_cleanup(NULL, &maintenance_result);

  lc_client_close(client);
  client = NULL;
  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;
  rc = lc_pouch_state_index_seq(handle->pouch, "default", &state_seq, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(state_seq > query_seq);
  assert_int_equal(manifest_seq, query_seq);

  /* The snapshot retained the last query-visible sequence for each document.
   * A wait flush must therefore remain a no-op despite newer lease metadata. */
  flush_req.mode = "wait";
  rc = client->flush_index(client, &flush_req, &flush_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(flush_res.index_seq, query_seq);
  lc_index_flush_res_cleanup(&flush_res);

  lc_update_res_cleanup(&second);
  lc_update_res_cleanup(&first);
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

/* A forced snapshot must retain the final cleared lease metadata for every
 * key. This exercises the dense metadata-only tail produced by a large
 * outbox: a stale pre-release record after reopen would make the dispatcher
 * treat a completed record as still leased until its original TTL expires. */
static void
test_compaction_reopen_preserves_released_implicit_xa_leases(void **state) {
  lc_client *client;
  lc_client_handle *handle;
  lc_pouch_maintenance_options maintenance_options;
  lc_pouch_maintenance_result maintenance_result;
  lc_update_res update_result;
  lc_acquire_req acquire_request;
  lc_lease *lease;
  lc_error error;
  char endpoint[1024];
  char root[512];
  char key[96];
  long document;
  long rewrite;
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  memset(&maintenance_options, 0, sizeof(maintenance_options));
  memset(&maintenance_result, 0, sizeof(maintenance_result));
  memset(&update_result, 0, sizeof(update_result));
  lc_acquire_req_init(&acquire_request);
  lc_error_init(&error);
  make_root("released-implicit-xa-compact", root, sizeof(root));
  cleanup_root(root);
  assert_true(snprintf(endpoint, sizeof(endpoint),
                       "pouch://%s?segment_target_bytes=65536&"
                       "indexer_flush_interval_seconds=3600",
                       root) > 0);

  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;
  for (rewrite = 0L; rewrite < 5L; ++rewrite) {
    for (document = 0L; document < 64L; ++document) {
      assert_true(
          snprintf(key, sizeof(key), "outbox/released-%03ld", document) > 0);
      write_client_state(client, key,
                         rewrite == 4L ? "{\"dispatch_state\":\"pending\"}"
                                       : "{\"dispatch_state\":\"completed\"}",
                         NULL, 0L, 0, &update_result, &error);
      lc_update_res_cleanup(&update_result);
      memset(&update_result, 0, sizeof(update_result));
    }
  }
  maintenance_options.namespace_name = "default";
  maintenance_options.force = 1;
  rc = lc_pouch_maintenance_run(handle->pouch, &maintenance_options,
                                &maintenance_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(maintenance_result.compacted);
  lc_pouch_maintenance_result_cleanup(NULL, &maintenance_result);
  lc_client_close(client);
  client = NULL;

  open_pouch_client_endpoint(endpoint, &client, &error);
  for (document = 0L; document < 64L; ++document) {
    assert_true(snprintf(key, sizeof(key), "outbox/released-%03ld", document) >
                0);
    acquire_request.key = key;
    acquire_request.owner = "pouch-compaction-regression";
    acquire_request.ttl_seconds = 30L;
    lease = NULL;
    rc = client->acquire(client, &acquire_request, &lease, &error);
    assert_int_equal(rc, LC_OK);
    assert_non_null(lease);
    rc = lease->release(lease, NULL, &error);
    assert_int_equal(rc, LC_OK);
    lease = NULL;
  }

  lc_update_res_cleanup(&update_result);
  lc_pouch_maintenance_result_cleanup(NULL, &maintenance_result);
  if (lease != NULL)
    lease->close(lease);
  if (client != NULL)
    lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_incremental_query_index_ignores_lease_only_key(void **state) {
  lc_client *client;
  lc_lease *lease;
  lc_acquire_req acquire_req;
  lc_update_res indexed_update;
  lc_update_res trigger_update;
  lc_index_flush_req flush_req;
  lc_index_flush_res flush_res;
  lc_query_req query_req;
  lc_query_res query_res;
  lc_query_key_handler handler;
  pouch_query_key_capture page;
  lc_error error;
  char endpoint[1024];
  char root[512];
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  memset(&indexed_update, 0, sizeof(indexed_update));
  memset(&trigger_update, 0, sizeof(trigger_update));
  lc_acquire_req_init(&acquire_req);
  lc_index_flush_req_init(&flush_req);
  memset(&flush_res, 0, sizeof(flush_res));
  lc_query_req_init(&query_req);
  memset(&query_res, 0, sizeof(query_res));
  memset(&handler, 0, sizeof(handler));
  memset(&page, 0, sizeof(page));
  lc_error_init(&error);
  make_root("incremental-index-lease-only", root, sizeof(root));
  cleanup_root(root);
  assert_true(snprintf(endpoint, sizeof(endpoint),
                       "pouch://%s?single_writer=true&"
                       "indexer_flush_interval_seconds=3600",
                       root) > 0);

  open_pouch_client_endpoint(endpoint, &client, &error);
  write_client_state(client, "doc/indexed", "{\"kind\":\"indexed\"}", NULL, 0L,
                     0, &indexed_update, &error);
  lc_update_res_cleanup(&indexed_update);

  flush_req.mode = "sync";
  rc = client->flush_index(client, &flush_req, &flush_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(flush_res.flushed);
  lc_index_flush_res_cleanup(&flush_res);
  memset(&flush_res, 0, sizeof(flush_res));

  acquire_req.key = "doc/lease-only";
  acquire_req.owner = "pouch-incremental-index";
  acquire_req.ttl_seconds = 30L;
  rc = client->acquire(client, &acquire_req, &lease, &error);
  assert_int_equal(rc, LC_OK);
  assert_non_null(lease);
  rc = lease->release(lease, NULL, &error);
  assert_int_equal(rc, LC_OK);
  lease = NULL;

  write_client_state(client, "doc/trigger", "{\"kind\":\"trigger\"}", NULL, 0L,
                     0, &trigger_update, &error);
  lc_update_res_cleanup(&trigger_update);

  rc = client->flush_index(client, &flush_req, &flush_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(flush_res.flushed);
  lc_index_flush_res_cleanup(&flush_res);

  handler.begin = pouch_query_key_begin;
  handler.chunk = pouch_query_key_chunk;
  handler.end = pouch_query_key_end;
  query_req.engine = "index";
  rc = client->query_keys(client, &query_req, &handler, &page, &query_res,
                          &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(page.count, 2);
  assert_true(pouch_query_capture_has(&page, "doc/indexed"));
  assert_true(pouch_query_capture_has(&page, "doc/trigger"));
  assert_false(pouch_query_capture_has(&page, "doc/lease-only"));

  lc_query_res_cleanup(&query_res);
  lc_update_res_cleanup(&trigger_update);
  lc_update_res_cleanup(&indexed_update);
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_query_index_ignores_internal_objects(void **state) {
  lc_client *client;
  lc_client_handle *handle;
  lc_acquire_req acquire_req;
  lc_attach_op attach_op;
  lc_attach_res attach_res;
  lc_enqueue_req enqueue_req;
  lc_enqueue_res enqueue_res;
  lc_dequeue_req dequeue_req;
  lc_dequeue_batch_res batch;
  lc_nack_op transaction_nack;
  lc_nack_res transaction_nack_res;
  lc_txn_participant transaction_participant;
  lc_txn_decision_req transaction_decision;
  lc_txn_decision_res transaction_decision_res;
  lc_query_req query_req;
  lc_query_res query_res;
  lc_query_key_handler query_handler;
  pouch_query_key_capture query_capture;
  lc_lease *lease;
  lc_message *transaction_message;
  lc_source *source;
  lc_update_res first;
  lc_update_res second;
  lc_pouch_generation manifest_seq;
  lc_pouch_generation query_seq;
  lc_pouch_generation state_seq;
  lc_error error;
  char endpoint[1024];
  char root[512];
  char transaction_participant_key[256];
  long message_index;
  size_t message_offset;
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  transaction_message = NULL;
  source = NULL;
  memset(&first, 0, sizeof(first));
  memset(&second, 0, sizeof(second));
  memset(&attach_res, 0, sizeof(attach_res));
  lc_enqueue_req_init(&enqueue_req);
  memset(&enqueue_res, 0, sizeof(enqueue_res));
  lc_dequeue_req_init(&dequeue_req);
  memset(&batch, 0, sizeof(batch));
  lc_nack_op_init(&transaction_nack);
  memset(&transaction_nack_res, 0, sizeof(transaction_nack_res));
  memset(&transaction_participant, 0, sizeof(transaction_participant));
  lc_txn_decision_req_init(&transaction_decision);
  memset(&transaction_decision_res, 0, sizeof(transaction_decision_res));
  lc_query_req_init(&query_req);
  memset(&query_res, 0, sizeof(query_res));
  memset(&query_handler, 0, sizeof(query_handler));
  memset(&query_capture, 0, sizeof(query_capture));
  manifest_seq = 0UL;
  query_seq = 0UL;
  state_seq = 0UL;
  lc_error_init(&error);
  make_root("query-index-internal-objects", root, sizeof(root));
  cleanup_root(root);
  assert_true(snprintf(endpoint, sizeof(endpoint),
                       "pouch://%s?indexer_flush_docs=2&"
                       "indexer_flush_interval_seconds=3600",
                       root) > 0);

  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;
  write_client_state(client, "doc/one", "{\"kind\":\"first\"}", NULL, 0L, 0,
                     &first, &error);
  write_client_state(client, "doc/two", "{\"kind\":\"second\"}", NULL, 0L, 0,
                     &second, &error);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);

  lc_acquire_req_init(&acquire_req);
  acquire_req.key = "doc/one";
  acquire_req.owner = "pouch-index-object";
  acquire_req.ttl_seconds = 30L;
  rc = client->acquire(client, &acquire_req, &lease, &error);
  assert_int_equal(rc, LC_OK);
  assert_non_null(lease);
  lc_attach_op_init(&attach_op);
  pouch_copy_lease_ref(&attach_op.lease, lease);
  attach_op.name = "opaque.bin";
  attach_op.content_type = "application/octet-stream";
  rc = lc_source_from_memory("\001\002not-json", 10U, &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->attach(client, &attach_op, source, &attach_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_source_close(source);
  source = NULL;
  lc_attach_res_cleanup(&attach_res);
  rc = lease->release(lease, NULL, &error);
  assert_int_equal(rc, LC_OK);
  lease = NULL;

  rc = lc_pouch_state_index_seq(handle->pouch, "default", &state_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(state_seq > query_seq);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);

  /* Batch delivery creates one fresh metadata-only delivery lease per message.
   * These control records must not advance public query freshness before or
   * after replay. This matches the production queue roundtrip workload. */
  enqueue_req.queue = "internal-objects";
  enqueue_req.visibility_timeout_seconds = 30L;
  for (message_index = 0L; message_index < 4L; ++message_index) {
    rc = lc_source_from_memory("payload", strlen("payload"), &source, &error);
    assert_int_equal(rc, LC_OK);
    rc = client->enqueue(client, &enqueue_req, source, &enqueue_res, &error);
    lc_source_close(source);
    source = NULL;
    assert_int_equal(rc, LC_OK);
    lc_enqueue_res_cleanup(&enqueue_res);
  }
  dequeue_req.queue = "internal-objects";
  dequeue_req.owner = "pouch-index-object";
  dequeue_req.visibility_timeout_seconds = 30L;
  dequeue_req.wait_seconds = 0L;
  dequeue_req.page_size = 4;
  rc = client->dequeue_batch(client, &dequeue_req, &batch, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(batch.count, 4U);
  for (message_offset = 0U; message_offset < batch.count; ++message_offset) {
    assert_non_null(batch.messages[message_offset]);
    rc = batch.messages[message_offset]->ack(batch.messages[message_offset],
                                             &error);
    assert_int_equal(rc, LC_OK);
    batch.messages[message_offset]->close(batch.messages[message_offset]);
    batch.messages[message_offset] = NULL;
  }
  lc_dequeue_batch_cleanup(&batch);
  rc = lc_pouch_state_index_seq(handle->pouch, "default", &state_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(state_seq > query_seq);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);
  lc_enqueue_res_cleanup(&enqueue_res);

  /* A queue update staged in a transaction is also an internal object. Its
   * promotion must neither enter the query projection nor leave an
   * uncompleted foreground-index operation behind. */
  enqueue_req.queue = "internal-objects-transaction";
  rc = lc_source_from_memory("payload", strlen("payload"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->enqueue(client, &enqueue_req, source, &enqueue_res, &error);
  lc_source_close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_enqueue_res_cleanup(&enqueue_res);

  lc_dequeue_req_init(&dequeue_req);
  dequeue_req.queue = "internal-objects-transaction";
  dequeue_req.owner = "pouch-index-object-transaction";
  dequeue_req.txn_id = test_xid_for_label("pouch-index-object-transaction");
  dequeue_req.visibility_timeout_seconds = 30L;
  dequeue_req.wait_seconds = 0L;
  rc = client->dequeue(client, &dequeue_req, &transaction_message, &error);
  assert_int_equal(rc, LC_OK);
  assert_non_null(transaction_message);

  transaction_nack.message.namespace_name = transaction_message->namespace_name;
  transaction_nack.message.queue = transaction_message->queue;
  transaction_nack.message.message_id = transaction_message->message_id;
  transaction_nack.message.lease_id = transaction_message->lease_id;
  transaction_nack.message.txn_id = transaction_message->txn_id;
  transaction_nack.message.fencing_token = transaction_message->fencing_token;
  transaction_nack.message.meta_etag = transaction_message->meta_etag;
  transaction_nack.intent = LC_NACK_INTENT_DEFER;
  rc = client->queue_nack(client, &transaction_nack, &transaction_nack_res,
                          &error);
  assert_int_equal(rc, LC_OK);
  assert_true(transaction_nack_res.requeued);
  lc_nack_res_cleanup(&transaction_nack_res);

  pouch_queue_message_participant_key(transaction_message,
                                      transaction_participant_key,
                                      sizeof(transaction_participant_key));
  transaction_participant.namespace_name = transaction_message->namespace_name;
  transaction_participant.key = transaction_participant_key;
  transaction_decision.txn_id = transaction_message->txn_id;
  transaction_decision.participants = &transaction_participant;
  transaction_decision.participant_count = 1U;
  rc = client->txn_commit(client, &transaction_decision,
                          &transaction_decision_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_txn_decision_res_cleanup(&transaction_decision_res);
  transaction_message->close(transaction_message);
  transaction_message = NULL;

  rc = lc_pouch_state_index_seq(handle->pouch, "default", &state_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(state_seq > query_seq);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);
  assert_false(lc_pouch_query_index_has_pending(handle->pouch, "default"));

  lc_client_close(client);
  client = NULL;
  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);

  /* A cold selector query must ignore opaque attachment bytes. Regressions
   * here mark scalar postings incomplete and strand workflow reconciliation. */
  query_handler.begin = pouch_query_key_begin;
  query_handler.chunk = pouch_query_key_chunk;
  query_handler.end = pouch_query_key_end;
  query_req.selector_json =
      "{\"eq\":{\"field\":\"/kind\",\"value\":\"first\"}}";
  query_req.engine = "index";
  query_req.refresh = "wait_for";
  query_req.limit = 10L;
  rc = client->query_keys(client, &query_req, &query_handler, &query_capture,
                          &query_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(query_capture.count, 1U);
  assert_true(pouch_query_capture_has(&query_capture, "doc/one"));
  assert_false(pouch_query_capture_has(&query_capture, "doc/two"));
  lc_query_res_cleanup(&query_res);

  lc_attach_res_cleanup(&attach_res);
  lc_nack_res_cleanup(&transaction_nack_res);
  lc_txn_decision_res_cleanup(&transaction_decision_res);
  lc_dequeue_batch_cleanup(&batch);
  lc_enqueue_res_cleanup(&enqueue_res);
  lc_update_res_cleanup(&second);
  lc_update_res_cleanup(&first);
  if (transaction_message != NULL) {
    transaction_message->close(transaction_message);
  }
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_staged_object_delete_does_not_queue_query_index(void **state) {
  lc_pouch *pouch;
  lc_pouch_state_write_options options;
  lc_pouch_state_write_result committed;
  lc_pouch_state_write_result staged;
  lc_pouch_state_write_result delete_result;
  lc_source *source;
  lc_pouch_generation query_seq;
  lc_error error;
  char root[512];
  int rc;

  (void)state;
  pouch = NULL;
  source = NULL;
  query_seq = 0UL;
  memset(&options, 0, sizeof(options));
  memset(&committed, 0, sizeof(committed));
  memset(&staged, 0, sizeof(staged));
  memset(&delete_result, 0, sizeof(delete_result));
  lc_error_init(&error);
  make_root("staged-object-delete-query-index", root, sizeof(root));
  cleanup_root(root);

  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  options.content_type = "application/octet-stream";
  options.object_record = 1;
  rc = lc_source_from_memory("object", strlen("object"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(pouch, "default", "internal/object", source,
                            &options, &committed, &error);
  lc_source_close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);

  options.staged_delete_marker = 1;
  options.has_query_hidden = 1;
  options.query_hidden = 1;
  rc = lc_source_from_memory("", 0U, &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_stage_write(pouch, "default", "internal/object",
                                  "object-delete", source, &options, &staged,
                                  &error);
  lc_source_close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_commit_staged(pouch, "default", "internal/object",
                                    "object-delete", &delete_result, &error);
  assert_int_equal(rc, LC_OK);

  rc = lc_pouch_state_query_index_seq(pouch, "default", &query_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(query_seq, 0UL);
  assert_false(lc_pouch_query_index_has_pending(pouch, "default"));

  lc_pouch_state_write_result_cleanup(NULL, &delete_result);
  lc_pouch_state_write_result_cleanup(NULL, &staged);
  lc_pouch_state_write_result_cleanup(NULL, &committed);
  lc_pouch_close(pouch);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void
test_query_index_threshold_handles_repeated_lease_updates(void **state) {
  lc_client *client;
  lc_client_handle *handle;
  lc_acquire_req acquire_req;
  lc_lease *lease;
  lc_source *source;
  lc_update_req update_req;
  lc_update_res update_res;
  lc_index_flush_req flush_req;
  lc_index_flush_res flush_res;
  lc_pouch_generation manifest_seq;
  lc_pouch_generation query_seq;
  lc_error error;
  char endpoint[1024];
  char key[32];
  char value[64];
  char root[512];
  long document;
  long update;
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  source = NULL;
  memset(&update_res, 0, sizeof(update_res));
  lc_index_flush_req_init(&flush_req);
  flush_req.mode = "wait";
  memset(&flush_res, 0, sizeof(flush_res));
  manifest_seq = 0UL;
  query_seq = 0UL;
  lc_error_init(&error);
  make_root("query-index-repeated-lease-updates", root, sizeof(root));
  cleanup_root(root);
  assert_true(snprintf(endpoint, sizeof(endpoint),
                       "pouch://%s?indexer_flush_docs=2&"
                       "indexer_flush_interval_seconds=3600",
                       root) > 0);
  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;

  for (document = 0L; document < 2L; ++document) {
    assert_true(snprintf(key, sizeof(key), "doc/%ld", document) > 0);
    lc_acquire_req_init(&acquire_req);
    acquire_req.key = key;
    acquire_req.owner = "pouch-index-threshold";
    acquire_req.ttl_seconds = 30L;
    lease = NULL;
    rc = client->acquire(client, &acquire_req, &lease, &error);
    assert_int_equal(rc, LC_OK);
    assert_non_null(lease);
    for (update = 0L; update < 2L; ++update) {
      assert_true(snprintf(value, sizeof(value),
                           "{\"kind\":\"doc-%ld-update-%ld\"}", document,
                           update) > 0);
      lc_update_req_init(&update_req);
      pouch_copy_lease_ref(&update_req.lease, lease);
      source = NULL;
      rc = lc_source_from_memory(value, strlen(value), &source, &error);
      assert_int_equal(rc, LC_OK);
      memset(&update_res, 0, sizeof(update_res));
      rc = client->update(client, &update_req, source, &update_res, &error);
      source->close(source);
      source = NULL;
      assert_int_equal(rc, LC_OK);
      lc_update_res_cleanup(&update_res);
    }
    if (document == 1L) {
      rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                          &error);
      assert_int_equal(rc, LC_OK);
      rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                             &manifest_seq, &error);
      assert_int_equal(rc, LC_OK);
      /* Go disk also flushes at the first mutation which reaches the
       * distinct-document threshold.  The second update of this key is a
       * valid one-document mutable tail until an explicit flush. */
      assert_true(manifest_seq < query_seq);
      rc = client->flush_index(client, &flush_req, &flush_res, &error);
      assert_int_equal(rc, LC_OK);
      assert_true(flush_res.flushed);
      lc_index_flush_res_cleanup(&flush_res);
      rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                             &manifest_seq, &error);
      assert_int_equal(rc, LC_OK);
      assert_int_equal(manifest_seq, query_seq);
    }
    rc = lease->release(lease, NULL, &error);
    assert_int_equal(rc, LC_OK);
    lease = NULL;
  }

  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  /* The last release follows the foreground flush and is one distinct
   * document tail, so it remains pending until a caller asks to publish it. */
  assert_true(manifest_seq < query_seq);
  rc = client->flush_index(client, &flush_req, &flush_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(flush_res.flushed);
  lc_index_flush_res_cleanup(&flush_res);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);

  lc_index_flush_res_cleanup(&flush_res);
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void
test_query_index_threshold_handles_deferred_first_lease_update(void **state) {
  static const char json_prefix[] = "{\"blob\":\"";
  static const char json_suffix[] = "\"}";
  static const char final_json[] = "{\"kind\":\"final\"}";
  lc_client *client;
  lc_client_handle *handle;
  lc_acquire_req acquire_req;
  lc_lease *lease;
  lc_source *source;
  lc_update_req update_req;
  lc_update_res update_res;
  lc_pouch_generation manifest_seq;
  lc_pouch_generation query_seq;
  lc_error error;
  char endpoint[1024];
  char root[512];
  char *large_json;
  size_t large_body_length;
  size_t large_json_length;
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  source = NULL;
  large_json = NULL;
  memset(&update_res, 0, sizeof(update_res));
  manifest_seq = 0UL;
  query_seq = 0UL;
  lc_error_init(&error);
  make_root("query-index-deferred-first-lease-update", root, sizeof(root));
  cleanup_root(root);
  assert_true(snprintf(endpoint, sizeof(endpoint),
                       "pouch://%s?indexer_flush_docs=1&"
                       "indexer_flush_interval_seconds=3600",
                       root) > 0);
  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;

  lc_acquire_req_init(&acquire_req);
  acquire_req.key = "doc/deferred-first";
  acquire_req.owner = "pouch-index-deferred-first";
  acquire_req.ttl_seconds = 30L;
  rc = client->acquire(client, &acquire_req, &lease, &error);
  assert_int_equal(rc, LC_OK);
  assert_non_null(lease);

  large_body_length = (64U * 1024U) + 4096U;
  large_json_length =
      sizeof(json_prefix) - 1U + large_body_length + sizeof(json_suffix) - 1U;
  large_json = (char *)malloc(large_json_length + 1U);
  assert_non_null(large_json);
  memcpy(large_json, json_prefix, sizeof(json_prefix) - 1U);
  memset(large_json + sizeof(json_prefix) - 1U, 'a', large_body_length);
  memcpy(large_json + sizeof(json_prefix) - 1U + large_body_length, json_suffix,
         sizeof(json_suffix) - 1U);
  large_json[large_json_length] = '\0';

  lc_update_req_init(&update_req);
  pouch_copy_lease_ref(&update_req.lease, lease);
  rc = lc_source_from_memory(large_json, large_json_length, &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->update(client, &update_req, source, &update_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_update_res_cleanup(&update_res);

  lc_update_req_init(&update_req);
  pouch_copy_lease_ref(&update_req.lease, lease);
  rc = lc_source_from_memory(final_json, strlen(final_json), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->update(client, &update_req, source, &update_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_update_res_cleanup(&update_res);

  rc = lease->release(lease, NULL, &error);
  assert_int_equal(rc, LC_OK);
  lease = NULL;
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);
  assert_false(lc_pouch_query_index_has_pending(handle->pouch, "default"));

  free(large_json);
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void pouch_remove_with_test_lease(lc_client *client,
                                         lc_remove_op *operation,
                                         lc_remove_res *out, lc_error *error) {
  lc_lease *lease;
  int rc;

  assert_non_null(operation);
  lease = NULL;
  pouch_acquire_test_lease(client, operation->lease.namespace_name,
                           operation->lease.key, NULL, &lease, error);
  pouch_copy_lease_ref(&operation->lease, lease);
  rc = client->remove(client, operation, out, error);
  assert_int_equal(rc, LC_OK);
  /* Acquires without a caller transaction ID are minted transactions. Their
   * staged remove becomes visible only when the lease is decided. */
  rc = lease->release(lease, NULL, error);
  assert_int_equal(rc, LC_OK);
}

static void test_public_core_contract_roundtrips_all_transforms(void **state) {
  static const char *const mode_names[] = {"plain", "crypto", "zlib",
                                           "crypto-zlib"};
  static const char state_json[] =
      "{\"category\":\"planning\",\"summary\":\"matrix full text\","
      "\"rank\":1}";
  static const char txn_json[] =
      "{\"category\":\"transaction\",\"summary\":\"matrix txn\"}";
  lc_client *client;
  lc_lease *lease;
  lc_source *source;
  lc_sink *sink;
  lc_acquire_req acquire_req;
  lc_keepalive_req keepalive_req;
  lc_mutate_req mutate_req;
  lc_get_opts public_get_opts;
  lc_get_res get_res;
  lc_attach_req attach_req;
  lc_attach_res attach_res;
  lc_attachment_get_req attachment_get_req;
  lc_attachment_get_res attachment_get_res;
  lc_enqueue_req enqueue_req;
  lc_enqueue_res enqueue_res;
  lc_dequeue_req dequeue_req;
  lc_message *message;
  lc_txn_participant participant;
  lc_txn_decision_req decision_req;
  lc_txn_decision_res decision_res;
  lc_query_req query_req;
  lc_query_res query_res;
  lc_query_key_handler query_handler;
  pouch_query_key_capture query_capture;
  lc_error error;
  const char *mutations[1];
  const void *bytes;
  size_t length;
  char *crypto_key;
  char root[512];
  unsigned int mode;
  int rc;

  (void)state;
  crypto_key = NULL;
  lc_error_init(&error);
  rc = lc_pouch_crypto_generate_key_string(&crypto_key, &error);
  assert_int_equal(rc, LC_OK);
  for (mode = 0U; mode < 4U; ++mode) {
    client = NULL;
    lease = NULL;
    source = NULL;
    sink = NULL;
    message = NULL;
    bytes = NULL;
    length = 0U;
    lc_acquire_req_init(&acquire_req);
    lc_keepalive_req_init(&keepalive_req);
    lc_mutate_req_init(&mutate_req);
    lc_get_opts_init(&public_get_opts);
    memset(&get_res, 0, sizeof(get_res));
    lc_attach_req_init(&attach_req);
    memset(&attach_res, 0, sizeof(attach_res));
    lc_attachment_get_req_init(&attachment_get_req);
    memset(&attachment_get_res, 0, sizeof(attachment_get_res));
    lc_enqueue_req_init(&enqueue_req);
    memset(&enqueue_res, 0, sizeof(enqueue_res));
    lc_dequeue_req_init(&dequeue_req);
    memset(&participant, 0, sizeof(participant));
    lc_txn_decision_req_init(&decision_req);
    memset(&decision_res, 0, sizeof(decision_res));
    lc_query_req_init(&query_req);
    memset(&query_res, 0, sizeof(query_res));
    memset(&query_handler, 0, sizeof(query_handler));
    memset(&query_capture, 0, sizeof(query_capture));
    make_root(mode_names[mode], root, sizeof(root));
    cleanup_root(root);
    pouch_open_transform_client(root, mode, crypto_key, &client, &error);

    acquire_req.key = "doc/core";
    acquire_req.owner = "matrix-owner";
    acquire_req.ttl_seconds = 30L;
    rc = client->acquire(client, &acquire_req, &lease, &error);
    assert_int_equal(rc, LC_OK);
    rc = lc_source_from_memory(state_json, strlen(state_json), &source, &error);
    assert_int_equal(rc, LC_OK);
    rc = lease->update(lease, source, NULL, &error);
    assert_int_equal(rc, LC_OK);
    lc_source_close(source);
    source = NULL;
    keepalive_req.ttl_seconds = 45L;
    rc = lease->keepalive(lease, &keepalive_req, &error);
    assert_int_equal(rc, LC_OK);
    mutations[0] = "/rank++";
    mutate_req.mutations = mutations;
    mutate_req.mutation_count = 1U;
    rc = lease->mutate(lease, &mutate_req, &error);
    assert_int_equal(rc, LC_OK);

    rc = lc_sink_to_memory(&sink, &error);
    assert_int_equal(rc, LC_OK);
    rc = lease->get(lease, sink, NULL, &get_res, &error);
    assert_int_equal(rc, LC_OK);
    rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
    assert_int_equal(rc, LC_OK);
    assert_true(bytes_contain_text(bytes, length, "\"rank\":2"));
    lc_sink_close(sink);
    sink = NULL;
    lc_get_res_cleanup(&get_res);

    attach_req.name = "matrix.txt";
    attach_req.content_type = "text/plain";
    rc = lc_source_from_memory("attachment", strlen("attachment"), &source,
                               &error);
    assert_int_equal(rc, LC_OK);
    rc = lease->attach(lease, &attach_req, source, &attach_res, &error);
    assert_int_equal(rc, LC_OK);
    lc_source_close(source);
    source = NULL;
    lc_attach_res_cleanup(&attach_res);
    attachment_get_req.selector.name = "matrix.txt";
    rc = lc_sink_to_memory(&sink, &error);
    assert_int_equal(rc, LC_OK);
    rc = lease->get_attachment(lease, &attachment_get_req, sink,
                               &attachment_get_res, &error);
    assert_int_equal(rc, LC_OK);
    rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
    assert_int_equal(rc, LC_OK);
    assert_int_equal(length, strlen("attachment"));
    assert_memory_equal(bytes, "attachment", length);
    lc_sink_close(sink);
    sink = NULL;
    lc_attachment_get_res_cleanup(&attachment_get_res);

    rc = lease->release(lease, NULL, &error);
    assert_int_equal(rc, LC_OK);
    lease = NULL;

    public_get_opts.public_read = 1;
    rc = lc_sink_to_memory(&sink, &error);
    assert_int_equal(rc, LC_OK);
    rc = client->get(client, "doc/core", &public_get_opts, sink, &get_res,
                     &error);
    assert_int_equal(rc, LC_OK);
    rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
    assert_int_equal(rc, LC_OK);
    assert_true(bytes_contain_text(bytes, length, "\"rank\":2"));
    lc_sink_close(sink);
    sink = NULL;
    lc_get_res_cleanup(&get_res);

    enqueue_req.queue = "matrix";
    enqueue_req.visibility_timeout_seconds = 30L;
    rc = lc_source_from_memory("queue", strlen("queue"), &source, &error);
    assert_int_equal(rc, LC_OK);
    rc = client->enqueue(client, &enqueue_req, source, &enqueue_res, &error);
    assert_int_equal(rc, LC_OK);
    lc_source_close(source);
    source = NULL;
    lc_enqueue_res_cleanup(&enqueue_res);
    dequeue_req.queue = "matrix";
    dequeue_req.owner = "matrix-worker";
    dequeue_req.visibility_timeout_seconds = 30L;
    rc = client->dequeue(client, &dequeue_req, &message, &error);
    assert_int_equal(rc, LC_OK);
    assert_non_null(message);
    rc = lc_sink_to_memory(&sink, &error);
    assert_int_equal(rc, LC_OK);
    rc = message->write_payload(message, sink, NULL, &error);
    assert_int_equal(rc, LC_OK);
    rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
    assert_int_equal(rc, LC_OK);
    assert_int_equal(length, strlen("queue"));
    assert_memory_equal(bytes, "queue", length);
    lc_sink_close(sink);
    sink = NULL;
    rc = message->ack(message, &error);
    assert_int_equal(rc, LC_OK);
    message = NULL;

    lc_acquire_req_init(&acquire_req);
    acquire_req.key = "doc/txn";
    acquire_req.owner = "matrix-txn-owner";
    acquire_req.ttl_seconds = 30L;
    acquire_req.txn_id = test_xid_for_label("matrix-txn");
    rc = client->acquire(client, &acquire_req, &lease, &error);
    assert_int_equal(rc, LC_OK);
    rc = lc_source_from_memory(txn_json, strlen(txn_json), &source, &error);
    assert_int_equal(rc, LC_OK);
    rc = lease->update(lease, source, NULL, &error);
    assert_int_equal(rc, LC_OK);
    lc_source_close(source);
    source = NULL;
    participant.namespace_name = "default";
    participant.key = "doc/txn";
    decision_req.txn_id = test_xid_for_label("matrix-txn");
    decision_req.participants = &participant;
    decision_req.participant_count = 1U;
    rc = client->txn_commit(client, &decision_req, &decision_res, &error);
    assert_int_equal(rc, LC_OK);
    lc_txn_decision_res_cleanup(&decision_res);
    lc_lease_close(lease);
    lease = NULL;

    query_handler.begin = pouch_query_key_begin;
    query_handler.chunk = pouch_query_key_chunk;
    query_handler.end = pouch_query_key_end;
    query_req.selector_json =
        "{\"eq\":{\"field\":\"/category\",\"value\":\"planning\"}}";
    query_req.engine = "scan";
    rc = client->query_keys(client, &query_req, &query_handler, &query_capture,
                            &query_res, &error);
    assert_int_equal(rc, LC_OK);
    assert_int_equal(query_capture.count, 1U);
    assert_true(pouch_query_capture_has(&query_capture, "doc/core"));
    lc_query_res_cleanup(&query_res);

    memset(&query_capture, 0, sizeof(query_capture));
    lc_query_req_init(&query_req);
    query_req.selector_json =
        "{\"eq\":{\"field\":\"/category\",\"value\":\"planning\"}}";
    query_req.engine = "index";
    query_req.refresh = "wait_for";
    rc = client->query_keys(client, &query_req, &query_handler, &query_capture,
                            &query_res, &error);
    assert_int_equal(rc, LC_OK);
    assert_int_equal(query_capture.count, 1U);
    assert_true(pouch_query_capture_has(&query_capture, "doc/core"));
    lc_query_res_cleanup(&query_res);

    memset(&query_capture, 0, sizeof(query_capture));
    lc_query_req_init(&query_req);
    query_req.selector_json =
        "{\"icontains\":{\"field\":\"/...\",\"value\":\"MATRIX FULL\"}}";
    query_req.engine = "index";
    query_req.refresh = "wait_for";
    rc = client->query_keys(client, &query_req, &query_handler, &query_capture,
                            &query_res, &error);
    assert_int_equal(rc, LC_OK);
    assert_int_equal(query_capture.count, 1U);
    assert_true(pouch_query_capture_has(&query_capture, "doc/core"));

    lc_query_res_cleanup(&query_res);
    lc_client_close(client);
    cleanup_root(root);
    lc_error_cleanup(&error);
    lc_error_init(&error);
  }
  lc_pouch_crypto_key_string_free(crypto_key);
  lc_error_cleanup(&error);
}

static void test_pouch_root_path_aliases_share_store_identity(void **state) {
  lc_client *canonical;
  lc_client *alias_client;
  lc_update_res first;
  lc_update_res second;
  lc_get_res get_res;
  lc_sink *sink;
  lc_error error;
  const void *sink_bytes;
  const char *leaf;
  size_t sink_length;
  char root[512];
  char alias_root[1100];
  char alias_endpoint[1200];
  int written;
  int rc;

  (void)state;
  canonical = NULL;
  alias_client = NULL;
  sink = NULL;
  memset(&first, 0, sizeof(first));
  memset(&second, 0, sizeof(second));
  memset(&get_res, 0, sizeof(get_res));
  sink_bytes = NULL;
  sink_length = 0U;
  lc_error_init(&error);
  make_root("root-path-alias", root, sizeof(root));
  cleanup_root(root);

  leaf = strrchr(root, '/');
  assert_non_null(leaf);
  ++leaf;
  written = snprintf(alias_root, sizeof(alias_root), "%s/../%s", root, leaf);
  assert_true(written > 0 && (size_t)written < sizeof(alias_root));
  written = snprintf(alias_endpoint, sizeof(alias_endpoint),
                     "pouch://%s?single_writer=false", alias_root);
  assert_true(written > 0 && (size_t)written < sizeof(alias_endpoint));

  open_pouch_client_shared(root, &canonical, &error);
  open_pouch_client_endpoint(alias_endpoint, &alias_client, &error);
  write_client_state(canonical, "alias/key", "{\"value\":1}", NULL, 0L, 0,
                     &first, &error);
  assert_int_equal(first.new_version, 1L);
  write_client_state(alias_client, "alias/key", "{\"value\":2}",
                     first.new_state_etag, 1L, 1, &second, &error);
  assert_int_equal(second.new_version, 2L);

  rc = lc_sink_to_memory(&sink, &error);
  assert_int_equal(rc, LC_OK);
  rc = canonical->get(canonical, "alias/key", NULL, sink, &get_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(get_res.no_content);
  rc = lc_sink_memory_bytes(sink, &sink_bytes, &sink_length, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(sink_length, strlen("{\"value\":2}"));
  assert_memory_equal(sink_bytes, "{\"value\":2}", sink_length);

  sink->close(sink);
  lc_get_res_cleanup(&get_res);
  lc_update_res_cleanup(&second);
  lc_update_res_cleanup(&first);
  lc_client_close(alias_client);
  lc_client_close(canonical);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

/* A transaction-minted normal lease must release while a shared-root namespace
 * mutation lock is active; the release path must not re-enter that lock. */
static void
test_shared_pouch_minted_lease_release_does_not_deadlock(void **state) {
  lc_client *client;
  lc_update_res update_res;
  lc_get_res get_res;
  lc_sink *sink;
  lc_error error;
  const void *bytes;
  size_t length;
  char root[512];
  int rc;

  (void)state;
  client = NULL;
  sink = NULL;
  memset(&update_res, 0, sizeof(update_res));
  memset(&get_res, 0, sizeof(get_res));
  lc_error_init(&error);
  make_root("shared-minted-release", root, sizeof(root));
  cleanup_root(root);
  open_pouch_client_shared(root, &client, &error);

  write_client_state(client, "state/shared-minted-release", "{\"value\":1}",
                     NULL, 0L, 0, &update_res, &error);
  rc = lc_sink_to_memory(&sink, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->get(client, "state/shared-minted-release", NULL, sink, &get_res,
                   &error);
  assert_int_equal(rc, LC_OK);
  assert_false(get_res.no_content);
  rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(length, strlen("{\"value\":1}"));
  assert_memory_equal(bytes, "{\"value\":1}", length);

  sink->close(sink);
  lc_get_res_cleanup(&get_res);
  lc_update_res_cleanup(&update_res);
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_state_etag_is_plaintext_sha256_content_hash(void **state) {
  lc_client *plain_client;
  lc_client *crypto_client;
  lc_update_res first;
  lc_update_res same;
  lc_update_res different;
  lc_update_res encrypted;
  lc_error error;
  char plain_root[512];
  char crypto_root[512];
  char *crypto_key;
  const char *payload;
  const char *other_payload;
  int rc;

  (void)state;
  plain_client = NULL;
  crypto_client = NULL;
  crypto_key = NULL;
  payload = "{\"deep\":{\"value\":42},\"summary\":\"same content\"}";
  other_payload = "{\"deep\":{\"value\":43},\"summary\":\"other content\"}";
  memset(&first, 0, sizeof(first));
  memset(&same, 0, sizeof(same));
  memset(&different, 0, sizeof(different));
  memset(&encrypted, 0, sizeof(encrypted));
  lc_error_init(&error);
  make_root("state-sha-etag-plain", plain_root, sizeof(plain_root));
  make_root("state-sha-etag-crypto", crypto_root, sizeof(crypto_root));
  cleanup_root(plain_root);
  cleanup_root(crypto_root);

  open_pouch_client(plain_root, &plain_client, &error);
  write_client_state(plain_client, "state/hash", payload, NULL, 0L, 0, &first,
                     &error);
  assert_sha256_text_etag(first.new_state_etag, payload);
  assert_int_equal(first.new_version, 1L);

  write_client_state(plain_client, "state/hash", payload, first.new_state_etag,
                     1L, 1, &same, &error);
  assert_string_equal(same.new_state_etag, first.new_state_etag);
  assert_int_equal(same.new_version, 2L);

  write_client_state(plain_client, "state/hash", other_payload,
                     same.new_state_etag, 2L, 1, &different, &error);
  assert_sha256_text_etag(different.new_state_etag, other_payload);
  assert_string_not_equal(different.new_state_etag, first.new_state_etag);
  assert_int_equal(different.new_version, 3L);
  lc_client_close(plain_client);
  plain_client = NULL;

  rc = lc_pouch_crypto_generate_key_string(&crypto_key, &error);
  assert_int_equal(rc, LC_OK);
  open_pouch_client_crypto(crypto_root, crypto_key, &crypto_client, &error);
  write_client_state(crypto_client, "state/hash", payload, NULL, 0L, 0,
                     &encrypted, &error);
  assert_string_equal(encrypted.new_state_etag, first.new_state_etag);
  assert_sha256_text_etag(encrypted.new_state_etag, payload);

  lc_update_res_cleanup(&encrypted);
  lc_update_res_cleanup(&different);
  lc_update_res_cleanup(&same);
  lc_update_res_cleanup(&first);
  lc_pouch_crypto_key_string_free(crypto_key);
  lc_client_close(crypto_client);
  cleanup_root(crypto_root);
  cleanup_root(plain_root);
  lc_error_cleanup(&error);
}

static int pouch_test_lock_shared_mutation_file(const char *root) {
  char *lock_path;
  struct flock fl;
  int fd;

  lock_path = lc_pouch_path_join(NULL, root, "pouch.mutation.lock");
  assert_non_null(lock_path);
  fd = open(lock_path, O_CREAT | O_RDWR, 0666);
  lc_free_with_allocator(NULL, lock_path);
  assert_true(fd >= 0);
  memset(&fl, 0, sizeof(fl));
  fl.l_type = F_WRLCK;
  fl.l_whence = SEEK_SET;
  assert_int_equal(fcntl(fd, F_SETLK, &fl), 0);
  return fd;
}

static void pouch_test_unlock_shared_mutation_file(int fd) {
  struct flock fl;

  memset(&fl, 0, sizeof(fl));
  fl.l_type = F_UNLCK;
  fl.l_whence = SEEK_SET;
  assert_int_equal(fcntl(fd, F_SETLK, &fl), 0);
  assert_int_equal(close(fd), 0);
}

