  cleanup_root(root);
  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_source_from_memory(payload, sizeof(payload) - 1U, &body, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_write(pouch, "default", "inline/record", body, NULL,
                            &write_result, &error);
  assert_int_equal(rc, LC_OK);
