  cleanup_root(root);
  fill_repeated_payload(payload, sizeof(payload));
  rc = lc_pouch_crypto_generate_key_string(&crypto_key, &error);
  assert_int_equal(rc, LC_OK);
  options.crypto_key = crypto_key;
  options.compression = "zlib";
