  lc_source_close(body);
  body = NULL;
  assert_int_equal(pthread_mutex_init(&overlap.mutex, NULL), 0);
  assert_int_equal(pthread_cond_init(&overlap.cond, NULL), 0);
  overlap.pouch = pouch;
