  written = snprintf(target, sizeof(target), "%s/target", root);
  assert_true(written > 0 && (size_t)written < sizeof(target));
  written = snprintf(key_path, sizeof(key_path), "%s/pouch.key", parent);
  assert_true(written > 0 && (size_t)written < sizeof(key_path));
  written = snprintf(target_key, sizeof(target_key), "%s/pouch.key", target);
  assert_true(written > 0 && (size_t)written < sizeof(target_key));
  assert_int_equal(mkdir(target, 0700), 0);
