  rc = lc_source_from_memory(
      "{\"created_at\":\"2026-01-01T00:00:00Z\",\"n\":1}",
      strlen("{\"created_at\":\"2026-01-01T00:00:00Z\",\"n\":1}"), &source,
      &error);
  assert_int_equal(rc, LC_OK);
