static void test_txn_decision_skips_foreign_backend_participant(void **state) {
  lc_client *client;
  lc_pouch *pouch;
  lc_source *source;
  lc_txn_participant participants[2];
  lc_txn_decision_req decision_req;
  lc_txn_decision_res decision_res;
  lc_pouch_state_write_result write_result;
  lc_pouch_state_read_result read_result;
  lc_error error;
  char root[512];
  char backend_hash[LC_POUCH_BACKEND_HASH_HEX_BYTES + 1U];
  char body[64];
  char staged_key[128];
  int rc;

  (void)state;
  client = NULL;
  pouch = NULL;
  source = NULL;
  memset(participants, 0, sizeof(participants));
  lc_txn_decision_req_init(&decision_req);
  memset(&decision_res, 0, sizeof(decision_res));
  memset(&write_result, 0, sizeof(write_result));
  memset(&read_result, 0, sizeof(read_result));
  lc_error_init(&error);
  make_root("txn-backend-routing", root, sizeof(root));
  cleanup_root(root);

  open_pouch_client(root, &client, &error);
  pouch = ((lc_client_handle *)client)->pouch;
  rc = lc_pouch_backend_hash(pouch, backend_hash, &error);
  assert_int_equal(rc, LC_OK);
  participants[0].namespace_name = "default";
  participants[0].key = "state/local";
  participants[0].backend_hash = backend_hash;
  participants[1].namespace_name = "default";
  participants[1].key = "state/foreign";
  participants[1].backend_hash = "foreign-backend";

  rc = lc_source_from_memory("local", strlen("local"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_stage_write(pouch, participants[0].namespace_name,
                                  participants[0].key,
                                  test_xid_for_label("txn-backend-routing"),
                                  source, NULL, &write_result, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_pouch_state_write_result_cleanup(NULL, &write_result);

  rc = lc_source_from_memory("foreign", strlen("foreign"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_stage_write(pouch, participants[1].namespace_name,
                                  participants[1].key,
                                  test_xid_for_label("txn-backend-routing"),
                                  source, NULL, &write_result, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_pouch_state_write_result_cleanup(NULL, &write_result);

  decision_req.txn_id = test_xid_for_label("txn-backend-routing");
  decision_req.participants = participants;
  decision_req.participant_count = 2U;
  rc = client->txn_commit(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_txn_decision_res_cleanup(&decision_res);

  rc = lc_pouch_state_read(pouch, participants[0].namespace_name,
                           participants[0].key, &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(read_result.found);
  read_source_to_string(read_result.body, body, sizeof(body));
  assert_string_equal(body, "local");
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  memset(&read_result, 0, sizeof(read_result));
  assert_true(snprintf(staged_key, sizeof(staged_key), "%s/.staging/%s",
                       participants[0].key,
                       test_xid_for_label("txn-backend-routing")) > 0);
  rc = lc_pouch_state_read(pouch, participants[0].namespace_name, staged_key,
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  memset(&read_result, 0, sizeof(read_result));

  rc = lc_pouch_state_read(pouch, participants[1].namespace_name,
                           participants[1].key, &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  memset(&read_result, 0, sizeof(read_result));
  assert_true(snprintf(staged_key, sizeof(staged_key), "%s/.staging/%s",
                       participants[1].key,
                       test_xid_for_label("txn-backend-routing")) > 0);
  rc = lc_pouch_state_read(pouch, participants[1].namespace_name, staged_key,
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(read_result.found);
  read_source_to_string(read_result.body, body, sizeof(body));
  assert_string_equal(body, "foreign");
  lc_pouch_state_read_result_cleanup(NULL, &read_result);

  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_txn_decision_validates_target_backend(void **state) {
  lc_client *client;
  lc_pouch *pouch;
  lc_txn_participant participant;
  lc_txn_decision_req decision_req;
  lc_txn_decision_res decision_res;
  lc_txn_replay_req replay_req;
  lc_txn_replay_res replay_res;
  lc_pouch_state_read_result read_result;
  lc_error error;
  char root[512];
  char backend_hash[LC_POUCH_BACKEND_HASH_HEX_BYTES + 1U];
  char padded_backend_hash[LC_POUCH_BACKEND_HASH_HEX_BYTES + 3U];
  int rc;

  (void)state;
  client = NULL;
  pouch = NULL;
  memset(&participant, 0, sizeof(participant));
  lc_txn_decision_req_init(&decision_req);
  memset(&decision_res, 0, sizeof(decision_res));
  lc_txn_replay_req_init(&replay_req);
  memset(&replay_res, 0, sizeof(replay_res));
  memset(&read_result, 0, sizeof(read_result));
  lc_error_init(&error);
  make_root("txn-target-backend", root, sizeof(root));
  cleanup_root(root);

  open_pouch_client(root, &client, &error);
  pouch = ((lc_client_handle *)client)->pouch;
  rc = lc_pouch_backend_hash(pouch, backend_hash, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(snprintf(padded_backend_hash, sizeof(padded_backend_hash), " %s ",
                       backend_hash) > 0);

  decision_req.txn_id = test_xid_for_label("txn-target-local");
  decision_req.target_backend_hash = padded_backend_hash;
  rc = client->txn_prepare(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_string_equal(decision_res.state, "prepare");
  lc_txn_decision_res_cleanup(&decision_res);

  decision_req.txn_id = test_xid_for_label("txn-target-foreign");
  decision_req.target_backend_hash = "foreign-backend";
  rc = client->txn_prepare(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_ERR_INVALID);
  assert_string_equal(error.message,
                      "pouch transaction target backend hash does not "
                      "match root");
  lc_error_cleanup(&error);
  lc_error_init(&error);
  rc = lc_pouch_state_read(pouch, ".txns",
                           test_xid_for_label("txn-target-foreign"),
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  memset(&read_result, 0, sizeof(read_result));

  participant.namespace_name = "default";
  participant.key = "state/blank-backend";
  participant.backend_hash = " \t ";
  decision_req.txn_id = test_xid_for_label("txn-target-blank-participant");
  decision_req.participants = &participant;
  decision_req.participant_count = 1U;
  decision_req.target_backend_hash = NULL;
  rc = client->txn_prepare(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_ERR_INVALID);
  assert_string_equal(error.message,
                      "pouch transaction participant backend hash is "
                      "invalid");
  lc_error_cleanup(&error);
  lc_error_init(&error);
  rc = lc_pouch_state_read(pouch, ".txns",
                           test_xid_for_label("txn-target-blank-participant"),
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  memset(&read_result, 0, sizeof(read_result));

  test_write_binary_txn_record(pouch, "txn-target-replay", "commit", 0L, 1UL,
                               "foreign-backend", NULL, 0U, &error);
  replay_req.txn_id = test_xid_for_label("txn-target-replay");
  rc = client->txn_replay(client, &replay_req, &replay_res, &error);
  assert_int_equal(rc, LC_ERR_INVALID);
  assert_string_equal(error.message,
                      "pouch transaction target backend hash does not "
                      "match root");
  lc_error_cleanup(&error);
  lc_error_init(&error);
  rc = lc_pouch_client_recover_transactions(client, &error);
  assert_int_equal(rc, LC_ERR_INVALID);
  assert_string_equal(error.message,
                      "pouch transaction target backend hash does not "
                      "match root");
  lc_error_cleanup(&error);
  lc_error_init(&error);
  rc = lc_pouch_state_read(pouch, ".txns",
                           test_xid_for_label("txn-target-replay"),
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);

  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_txn_decisions_apply_attachment_side_effects(void **state) {
  lc_client *client;
  lc_lease *commit_lease;
  lc_lease *rollback_lease;
  lc_source *source;
  lc_sink *sink;
  lc_txn_participant participant;
  lc_txn_decision_req decision_req;
  lc_txn_decision_res decision_res;
  lc_attach_op attach_op;
  lc_attach_res attach_res;
  lc_attachment_list_req list_req;
  lc_attachment_list list;
  lc_attachment_get_op get_op;
  lc_attachment_get_res get_res;
  lc_error error;
  const void *bytes;
  size_t length;
  lc_unix_seconds created_at_unix;
  lc_unix_seconds updated_at_unix;
  char root[512];
  int rc;

  (void)state;
  client = NULL;
  commit_lease = NULL;
  rollback_lease = NULL;
  source = NULL;
  sink = NULL;
  memset(&participant, 0, sizeof(participant));
  lc_txn_decision_req_init(&decision_req);
  memset(&decision_res, 0, sizeof(decision_res));
  lc_attach_op_init(&attach_op);
  memset(&attach_res, 0, sizeof(attach_res));
  lc_attachment_list_req_init(&list_req);
  memset(&list, 0, sizeof(list));
  lc_attachment_get_op_init(&get_op);
  memset(&get_res, 0, sizeof(get_res));
  lc_error_init(&error);
  bytes = NULL;
  length = 0U;
  created_at_unix = 0L;
  updated_at_unix = 0L;
  make_root("txn-attachments", root, sizeof(root));
  cleanup_root(root);

  open_pouch_client(root, &client, &error);
  attach_op.lease.namespace_name = "objects/txn";
  attach_op.lease.key = "state/object-1";
  attach_op.lease.txn_id = test_xid_for_label("txn-attachment-commit");
  pouch_acquire_test_lease(client, "objects/txn", "state/object-1",
                           attach_op.lease.txn_id, &commit_lease, &error);
  pouch_copy_lease_ref(&attach_op.lease, commit_lease);
  attach_op.name = "report.txt";
  attach_op.content_type = "text/plain";
  attach_op.prevent_overwrite = 1;
  rc = lc_source_from_memory("committed-object", strlen("committed-object"),
                             &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->attach(client, &attach_op, source, &attach_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  assert_true(attach_res.attachment.created_at_unix > 1000000000L);
  assert_true(attach_res.attachment.updated_at_unix >=
              attach_res.attachment.created_at_unix);
  created_at_unix = attach_res.attachment.created_at_unix;
  updated_at_unix = attach_res.attachment.updated_at_unix;
  lc_attach_res_cleanup(&attach_res);

  list_req.lease.namespace_name = "objects/txn";
  list_req.lease.key = "state/object-1";
  list_req.public_read = 1;
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(list.count, 0U);
  lc_attachment_list_cleanup(&list);

  participant.namespace_name = "objects/txn";
  participant.key = "state/object-1";
  participant.backend_hash = NULL;
  decision_req.txn_id = test_xid_for_label("txn-attachment-commit");
  decision_req.participants = &participant;
  decision_req.participant_count = 1U;
  rc = client->txn_commit(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_string_equal(decision_res.state, "commit");
  lc_txn_decision_res_cleanup(&decision_res);
  commit_lease->close(commit_lease);
  commit_lease = NULL;

  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(list.count, 1U);
  assert_string_equal(list.items[0].name, "report.txt");
  assert_int_equal(list.items[0].created_at_unix, created_at_unix);
  assert_true(list.items[0].updated_at_unix >= updated_at_unix);
  lc_attachment_list_cleanup(&list);

  get_op.lease.namespace_name = "objects/txn";
  get_op.lease.key = "state/object-1";
  get_op.public_read = 1;
  get_op.selector.name = "report.txt";
  rc = lc_sink_to_memory(&sink, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->get_attachment(client, &get_op, sink, &get_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(get_res.attachment.created_at_unix, created_at_unix);
  assert_true(get_res.attachment.updated_at_unix >= updated_at_unix);
  rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(length, strlen("committed-object"));
  assert_memory_equal(bytes, "committed-object", strlen("committed-object"));
  sink->close(sink);
  sink = NULL;
  lc_attachment_get_res_cleanup(&get_res);

  attach_op.lease.txn_id = test_xid_for_label("txn-attachment-rollback");
  pouch_acquire_test_lease(client, "objects/txn", "state/object-1",
                           attach_op.lease.txn_id, &rollback_lease, &error);
  pouch_copy_lease_ref(&attach_op.lease, rollback_lease);
  attach_op.name = "report.txt";
  rc = lc_source_from_memory("replacement", strlen("replacement"), &source,
                             &error);
  assert_int_equal(rc, LC_OK);
  rc = client->attach(client, &attach_op, source, &attach_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_ERR_INVALID);
  assert_non_null(strstr(error.message, "already exists"));
  lc_error_cleanup(&error);
  lc_error_init(&error);
  lc_attach_res_cleanup(&attach_res);

  attach_op.name = "rolled-back.txt";
  rc = lc_source_from_memory("rolled-back-object", strlen("rolled-back-object"),
                             &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->attach(client, &attach_op, source, &attach_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_attach_res_cleanup(&attach_res);

  decision_req.txn_id = test_xid_for_label("txn-attachment-rollback");
  rc = client->txn_rollback(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_string_equal(decision_res.state, "rollback");
  lc_txn_decision_res_cleanup(&decision_res);
  rollback_lease->close(rollback_lease);
  rollback_lease = NULL;

  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(list.count, 1U);
  assert_string_equal(list.items[0].name, "report.txt");
  lc_attachment_list_cleanup(&list);

  if (rollback_lease != NULL) {
    rollback_lease->close(rollback_lease);
  }
  if (commit_lease != NULL) {
    commit_lease->close(commit_lease);
  }
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_txn_recovery_applies_attachment_side_effects(void **state) {
  lc_client *client;
  lc_pouch *pouch;
  lc_lease *lease;
  lc_source *source;
  lc_attach_op attach_op;
  lc_attach_res attach_res;
  lc_attachment_list_req list_req;
  lc_attachment_list list;
  lc_pouch_state_write_result write_result;
  lc_pouch_state_read_result read_result;
  lc_error error;
  char root[512];
  int rc;

  (void)state;
  client = NULL;
  pouch = NULL;
  lease = NULL;
  source = NULL;
  lc_attach_op_init(&attach_op);
  memset(&attach_res, 0, sizeof(attach_res));
  lc_attachment_list_req_init(&list_req);
  memset(&list, 0, sizeof(list));
  memset(&write_result, 0, sizeof(write_result));
  memset(&read_result, 0, sizeof(read_result));
  lc_error_init(&error);
  make_root("txn-attachment-recovery", root, sizeof(root));
  cleanup_root(root);

  open_pouch_client(root, &client, &error);
  attach_op.lease.namespace_name = "objects/recover";
  attach_op.lease.key = "state/object-2";
  attach_op.lease.txn_id = test_xid_for_label("txn-attachment-recover");
  pouch_acquire_test_lease(client, "objects/recover", "state/object-2",
                           attach_op.lease.txn_id, &lease, &error);
  pouch_copy_lease_ref(&attach_op.lease, lease);
  attach_op.name = "recovered.txt";
  attach_op.content_type = "text/plain";
  rc = lc_source_from_memory("recovered-object", strlen("recovered-object"),
                             &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->attach(client, &attach_op, source, &attach_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_attach_res_cleanup(&attach_res);
  lease->close(lease);
  lease = NULL;
  lc_client_close(client);
  client = NULL;

  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  {
    lc_txn_participant participant;

    memset(&participant, 0, sizeof(participant));
    participant.namespace_name = "objects/recover";
    participant.key = "state/object-2";
    participant.backend_hash = NULL;
    test_write_binary_txn_record(pouch, "txn-attachment-recover", "commit", 0L,
                                 1UL, "", &participant, 1U, &error);
  }
  lc_pouch_close(pouch);
  pouch = NULL;

  open_pouch_client(root, &client, &error);
  list_req.lease.namespace_name = "objects/recover";
  list_req.lease.key = "state/object-2";
  list_req.public_read = 1;
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(list.count, 1U);
  assert_string_equal(list.items[0].name, "recovered.txt");
  lc_attachment_list_cleanup(&list);
  lc_client_close(client);
  client = NULL;

  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_read(pouch, ".txns",
                           test_xid_for_label("txn-attachment-recover"),
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  lc_pouch_close(pouch);
  pouch = NULL;

  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void pouch_attach_text_with_lease(lc_lease *lease, const char *name,
                                         const char *body, lc_error *error) {
  lc_attach_req attach_req;
  lc_attach_res attach_res;
  lc_source *source;
  int rc;

  lc_attach_req_init(&attach_req);
  memset(&attach_res, 0, sizeof(attach_res));
  source = NULL;
  attach_req.name = name;
  attach_req.content_type = "text/plain";
  rc = lc_source_from_memory(body, strlen(body), &source, error);
  assert_int_equal(rc, LC_OK);
  rc = lease->attach(lease, &attach_req, source, &attach_res, error);
  source->close(source);
  assert_int_equal(rc, LC_OK);
  lc_attach_res_cleanup(&attach_res);
}

static void pouch_attach_text(lc_client *client, const char *namespace_name,
                              const char *key, const char *txn_id,
                              const char *name, const char *body,
                              lc_error *error) {
  lc_lease *lease;
  int rc;

  lease = NULL;
  pouch_acquire_test_lease(client, namespace_name, key, txn_id, &lease, error);
  pouch_attach_text_with_lease(lease, name, body, error);
  if (txn_id != NULL) {
    lease->close(lease);
  } else {
    rc = lease->release(lease, NULL, error);
    assert_int_equal(rc, LC_OK);
  }
}

static int pouch_attachment_list_has_name(const lc_attachment_list *list,
                                          const char *name) {
  size_t i;

  for (i = 0U; i < list->count; ++i) {
    if (strcmp(list->items[i].name, name) == 0) {
      return 1;
    }
  }
  return 0;
}

static void
test_private_attachment_reads_validate_lease_and_overlay_transaction(
    void **state) {
  lc_client *client;
  lc_lease *lease;
  lc_source *source;
  lc_sink *sink;
  lc_acquire_req acquire_req;
  lc_attach_req attach_req;
  lc_attachment_selector selector;
  lc_attachment_get_req get_req;
  lc_attachment_list_req list_req;
  lc_attachment_list list;
  lc_attachment_get_res get_res;
  lc_attach_res attach_res;
  lc_error error;
  const void *bytes;
  size_t length;
  char root[512];
  int deleted;
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  source = NULL;
  sink = NULL;
  bytes = NULL;
  length = 0U;
  deleted = 0;
  lc_acquire_req_init(&acquire_req);
  lc_attach_req_init(&attach_req);
  memset(&selector, 0, sizeof(selector));
  lc_attachment_get_req_init(&get_req);
  lc_attachment_list_req_init(&list_req);
  memset(&list, 0, sizeof(list));
  memset(&get_res, 0, sizeof(get_res));
  memset(&attach_res, 0, sizeof(attach_res));
  lc_error_init(&error);
  make_root("attachment-txn-read", root, sizeof(root));
  cleanup_root(root);

  open_pouch_client(root, &client, &error);
  pouch_attach_text(client, "docs/attachment-txn", "state/attachment-txn", NULL,
                    "old.txt", "old", &error);

  acquire_req.namespace_name = "docs/attachment-txn";
  acquire_req.key = "state/attachment-txn";
  acquire_req.owner = "attachment-txn-owner";
  acquire_req.ttl_seconds = 30L;
  acquire_req.txn_id = test_xid_for_label("txn-attachment-read");
  rc = client->acquire(client, &acquire_req, &lease, &error);
  assert_int_equal(rc, LC_OK);

  attach_req.name = "new.txt";
  attach_req.content_type = "text/plain";
  rc = lc_source_from_memory("new", strlen("new"), &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lease->attach(lease, &attach_req, source, &attach_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_attach_res_cleanup(&attach_res);

  selector.name = "old.txt";
  rc = lease->delete_attachment(lease, &selector, &deleted, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(deleted, 1);

  list_req.lease.namespace_name = acquire_req.namespace_name;
  list_req.lease.key = acquire_req.key;
  list_req.lease.txn_id = acquire_req.txn_id;
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_ERR_INVALID);
  lc_error_cleanup(&error);
  lc_error_init(&error);

  rc = lease->list_attachments(lease, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(list.count, 1U);
  assert_true(pouch_attachment_list_has_name(&list, "new.txt"));
  assert_false(pouch_attachment_list_has_name(&list, "old.txt"));
  lc_attachment_list_cleanup(&list);

  get_req.selector.name = "new.txt";
  rc = lc_sink_to_memory(&sink, &error);
  assert_int_equal(rc, LC_OK);
  rc = lease->get_attachment(lease, &get_req, sink, &get_res, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(length, strlen("new"));
  assert_memory_equal(bytes, "new", length);
  lc_attachment_get_res_cleanup(&get_res);
  sink->close(sink);
  sink = NULL;

  list_req.public_read = 1;
  list_req.lease.txn_id = NULL;
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(list.count, 1U);
  assert_true(pouch_attachment_list_has_name(&list, "old.txt"));
  assert_false(pouch_attachment_list_has_name(&list, "new.txt"));
  lc_attachment_list_cleanup(&list);

  lc_lease_close(lease);
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void
test_txn_decisions_apply_mixed_object_queue_side_effects(void **state) {
  lc_client *client;
  lc_source *source;
  lc_txn_participant participants[2];
  lc_txn_decision_req decision_req;
  lc_txn_decision_res decision_res;
  lc_attachment_list_req list_req;
  lc_attachment_list list;
  lc_enqueue_req enqueue_req;
  lc_enqueue_res enqueue_res;
  lc_dequeue_req dequeue_req;
  lc_queue_stats_req stats_req;
  lc_queue_stats_res stats_res;
  lc_ack_op ack_op;
  lc_ack_res ack_res;
  lc_message *message;
  lc_error error;
  char root[512];
  char queue_participant_key[256];
  int rc;

  (void)state;
  client = NULL;
  source = NULL;
  message = NULL;
  memset(participants, 0, sizeof(participants));
  lc_txn_decision_req_init(&decision_req);
  memset(&decision_res, 0, sizeof(decision_res));
  lc_attachment_list_req_init(&list_req);
  memset(&list, 0, sizeof(list));
  lc_enqueue_req_init(&enqueue_req);
  memset(&enqueue_res, 0, sizeof(enqueue_res));
  lc_dequeue_req_init(&dequeue_req);
  lc_queue_stats_req_init(&stats_req);
  memset(&stats_res, 0, sizeof(stats_res));
  memset(&ack_op, 0, sizeof(ack_op));
  memset(&ack_res, 0, sizeof(ack_res));
  lc_error_init(&error);
  make_root("txn-mixed-object-queue", root, sizeof(root));
  cleanup_root(root);

  open_pouch_client(root, &client, &error);
  list_req.lease.namespace_name = "objects/mixed";
  list_req.lease.key = "state/object-queue";
  list_req.public_read = 1;
  participants[0].namespace_name = "objects/mixed";
  participants[0].key = "state/object-queue";
  participants[0].backend_hash = NULL;
  decision_req.participants = participants;
  decision_req.participant_count = 1U;
  enqueue_req.namespace_name = "objects/mixed";
  enqueue_req.queue = "mixed-q";
  enqueue_req.visibility_timeout_seconds = 120L;
  dequeue_req.namespace_name = "objects/mixed";
  dequeue_req.queue = "mixed-q";
  dequeue_req.owner = "mixed-worker";
  dequeue_req.visibility_timeout_seconds = 120L;
  stats_req.namespace_name = "objects/mixed";
  stats_req.queue = "mixed-q";

  pouch_attach_text(client, "objects/mixed", "state/object-queue",
                    "txn-mixed-commit", "commit.txt", "commit", &error);
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(pouch_attachment_list_has_name(&list, "commit.txt"));
  lc_attachment_list_cleanup(&list);

  rc = lc_source_from_memory("commit-job", strlen("commit-job"), &source,
                             &error);
  assert_int_equal(rc, LC_OK);
  rc = client->enqueue(client, &enqueue_req, source, &enqueue_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_enqueue_res_cleanup(&enqueue_res);
  dequeue_req.txn_id = test_xid_for_label("txn-mixed-commit");
  rc = client->dequeue(client, &dequeue_req, &message, &error);
  assert_int_equal(rc, LC_OK);
  assert_non_null(message);
  ack_op.message.namespace_name = message->namespace_name;
  ack_op.message.queue = message->queue;
  ack_op.message.message_id = message->message_id;
  ack_op.message.lease_id = message->lease_id;
  ack_op.message.txn_id = message->txn_id;
  ack_op.message.fencing_token = message->fencing_token;
  ack_op.message.meta_etag = message->meta_etag;
  rc = client->queue_ack(client, &ack_op, &ack_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(ack_res.acked, 1);
  lc_ack_res_cleanup(&ack_res);
  rc = client->queue_stats(client, &stats_req, &stats_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(stats_res.pending_candidates, 1);
  lc_queue_stats_res_cleanup(&stats_res);
  decision_req.txn_id = test_xid_for_label("txn-mixed-commit");
  pouch_queue_message_participant_key(message, queue_participant_key,
                                      sizeof(queue_participant_key));
  participants[1].namespace_name = message->namespace_name;
  participants[1].key = queue_participant_key;
  participants[1].backend_hash = NULL;
  decision_req.participant_count = 2U;
  rc = client->txn_commit(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_txn_decision_res_cleanup(&decision_res);
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(pouch_attachment_list_has_name(&list, "commit.txt"));
  lc_attachment_list_cleanup(&list);
  rc = client->queue_stats(client, &stats_req, &stats_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(stats_res.pending_candidates, 0);
  lc_queue_stats_res_cleanup(&stats_res);
  message->close(message);
  message = NULL;

  pouch_attach_text(client, "objects/mixed", "state/object-queue",
                    "txn-mixed-rollback", "rollback.txt", "rollback", &error);
  rc = lc_source_from_memory("rollback-job", strlen("rollback-job"), &source,
                             &error);
  assert_int_equal(rc, LC_OK);
  rc = client->enqueue(client, &enqueue_req, source, &enqueue_res, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_enqueue_res_cleanup(&enqueue_res);
  dequeue_req.txn_id = test_xid_for_label("txn-mixed-rollback");
  rc = client->dequeue(client, &dequeue_req, &message, &error);
  assert_int_equal(rc, LC_OK);
  assert_non_null(message);
  memset(&ack_op, 0, sizeof(ack_op));
  memset(&ack_res, 0, sizeof(ack_res));
  ack_op.message.namespace_name = message->namespace_name;
  ack_op.message.queue = message->queue;
  ack_op.message.message_id = message->message_id;
  ack_op.message.lease_id = message->lease_id;
  ack_op.message.txn_id = message->txn_id;
  ack_op.message.fencing_token = message->fencing_token;
  ack_op.message.meta_etag = message->meta_etag;
  rc = client->queue_ack(client, &ack_op, &ack_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(ack_res.acked, 1);
  lc_ack_res_cleanup(&ack_res);
  decision_req.txn_id = test_xid_for_label("txn-mixed-rollback");
  pouch_queue_message_participant_key(message, queue_participant_key,
                                      sizeof(queue_participant_key));
  participants[1].namespace_name = message->namespace_name;
  participants[1].key = queue_participant_key;
  participants[1].backend_hash = NULL;
  decision_req.participant_count = 2U;
  rc = client->txn_rollback(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_txn_decision_res_cleanup(&decision_res);
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(pouch_attachment_list_has_name(&list, "commit.txt"));
  assert_false(pouch_attachment_list_has_name(&list, "rollback.txt"));
  lc_attachment_list_cleanup(&list);
  ack_op.message.txn_id = NULL;
  memset(&ack_res, 0, sizeof(ack_res));
  rc = client->queue_ack(client, &ack_op, &ack_res, &error);
  assert_true(rc != LC_OK);
  lc_error_cleanup(&error);
  lc_error_init(&error);
  lc_ack_res_cleanup(&ack_res);
  message->close(message);
  message = NULL;

  dequeue_req.txn_id = NULL;
  rc = client->dequeue(client, &dequeue_req, &message, &error);
  assert_int_equal(rc, LC_OK);
  assert_non_null(message);
  memset(&ack_op, 0, sizeof(ack_op));
  memset(&ack_res, 0, sizeof(ack_res));
  ack_op.message.namespace_name = message->namespace_name;
  ack_op.message.queue = message->queue;
  ack_op.message.message_id = message->message_id;
  ack_op.message.lease_id = message->lease_id;
  ack_op.message.fencing_token = message->fencing_token;
  ack_op.message.meta_etag = message->meta_etag;
  rc = client->queue_ack(client, &ack_op, &ack_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(ack_res.acked, 1);
  lc_ack_res_cleanup(&ack_res);
  message->close(message);
  message = NULL;

  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_txn_decisions_apply_attachment_delete_and_clear(void **state) {
  lc_client *client;
  lc_lease *lease;
  lc_txn_participant participant;
  lc_txn_decision_req decision_req;
  lc_txn_decision_res decision_res;
  lc_attachment_delete_op delete_op;
  lc_attachment_delete_all_op delete_all_op;
  lc_attachment_list_req list_req;
  lc_attachment_list list;
  lc_error error;
  char root[512];
  int deleted;
  int deleted_count;
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  memset(&participant, 0, sizeof(participant));
  lc_txn_decision_req_init(&decision_req);
  memset(&decision_res, 0, sizeof(decision_res));
  lc_attachment_delete_op_init(&delete_op);
  lc_attachment_delete_all_op_init(&delete_all_op);
  lc_attachment_list_req_init(&list_req);
  memset(&list, 0, sizeof(list));
  lc_error_init(&error);
  make_root("txn-attachment-delete", root, sizeof(root));
  cleanup_root(root);

  open_pouch_client(root, &client, &error);
  pouch_attach_text(client, "objects/delete", "state/object-3", NULL,
                    "keep.txt", "keep", &error);
  pouch_attach_text(client, "objects/delete", "state/object-3", NULL,
                    "delete.txt", "delete", &error);
  pouch_attach_text(client, "objects/delete", "state/object-3", NULL,
                    "rollback-delete.txt", "rollback-delete", &error);

  list_req.lease.namespace_name = "objects/delete";
  list_req.lease.key = "state/object-3";
  list_req.public_read = 1;
  delete_op.lease.namespace_name = "objects/delete";
  delete_op.lease.key = "state/object-3";
  delete_op.lease.txn_id = test_xid_for_label("txn-delete-commit");
  pouch_acquire_test_lease(client, "objects/delete", "state/object-3",
                           delete_op.lease.txn_id, &lease, &error);
  pouch_copy_lease_ref(&delete_op.lease, lease);
  delete_op.selector.name = "delete.txt";
  deleted = 0;
  rc = client->delete_attachment(client, &delete_op, &deleted, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(deleted, 1);

  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(pouch_attachment_list_has_name(&list, "delete.txt"));
  lc_attachment_list_cleanup(&list);

  participant.namespace_name = "objects/delete";
  participant.key = "state/object-3";
  participant.backend_hash = NULL;
  decision_req.txn_id = test_xid_for_label("txn-delete-commit");
  decision_req.participants = &participant;
  decision_req.participant_count = 1U;
  rc = client->txn_commit(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_txn_decision_res_cleanup(&decision_res);
  lease->close(lease);
  lease = NULL;

  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(pouch_attachment_list_has_name(&list, "delete.txt"));
  assert_true(pouch_attachment_list_has_name(&list, "keep.txt"));
  assert_true(pouch_attachment_list_has_name(&list, "rollback-delete.txt"));
  lc_attachment_list_cleanup(&list);

  delete_op.lease.txn_id = test_xid_for_label("txn-delete-rollback");
  pouch_acquire_test_lease(client, "objects/delete", "state/object-3",
                           delete_op.lease.txn_id, &lease, &error);
  pouch_copy_lease_ref(&delete_op.lease, lease);
  delete_op.selector.name = "rollback-delete.txt";
  deleted = 0;
  rc = client->delete_attachment(client, &delete_op, &deleted, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(deleted, 1);
  decision_req.txn_id = test_xid_for_label("txn-delete-rollback");
  rc = client->txn_rollback(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_txn_decision_res_cleanup(&decision_res);
  lease->close(lease);
  lease = NULL;
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(pouch_attachment_list_has_name(&list, "rollback-delete.txt"));
  lc_attachment_list_cleanup(&list);

  pouch_attach_text(client, "objects/delete", "state/object-3", NULL,
                    "clear-a.txt", "clear-a", &error);
  pouch_attach_text(client, "objects/delete", "state/object-3", NULL,
                    "clear-b.txt", "clear-b", &error);
  pouch_acquire_test_lease(client, "objects/delete", "state/object-3",
                           "txn-clear-commit", &lease, &error);
  pouch_attach_text_with_lease(lease, "staged-clear.txt", "staged-clear",
                               &error);
  delete_all_op.lease.namespace_name = "objects/delete";
  delete_all_op.lease.key = "state/object-3";
  delete_all_op.lease.txn_id = test_xid_for_label("txn-clear-commit");
  pouch_copy_lease_ref(&delete_all_op.lease, lease);
  deleted_count = 0;
  rc = client->delete_all_attachments(client, &delete_all_op, &deleted_count,
                                      &error);
  assert_int_equal(rc, LC_OK);
  assert_true(deleted_count >= 4);
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(list.count >= 4U);
  lc_attachment_list_cleanup(&list);
  decision_req.txn_id = test_xid_for_label("txn-clear-commit");
  rc = client->txn_commit(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_txn_decision_res_cleanup(&decision_res);
  lease->close(lease);
  lease = NULL;
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(list.count, 0U);
  lc_attachment_list_cleanup(&list);

  pouch_attach_text(client, "objects/delete", "state/object-3", NULL,
                    "rollback-clear.txt", "rollback-clear", &error);
  delete_all_op.lease.txn_id = test_xid_for_label("txn-clear-rollback");
  pouch_acquire_test_lease(client, "objects/delete", "state/object-3",
                           delete_all_op.lease.txn_id, &lease, &error);
  pouch_copy_lease_ref(&delete_all_op.lease, lease);
  deleted_count = 0;
  rc = client->delete_all_attachments(client, &delete_all_op, &deleted_count,
                                      &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(deleted_count, 1);
  decision_req.txn_id = test_xid_for_label("txn-clear-rollback");
  rc = client->txn_rollback(client, &decision_req, &decision_res, &error);
  assert_int_equal(rc, LC_OK);
  lc_txn_decision_res_cleanup(&decision_res);
  lease->close(lease);
  lease = NULL;
  rc = client->list_attachments(client, &list_req, &list, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(list.count, 1U);
  assert_string_equal(list.items[0].name, "rollback-clear.txt");
  lc_attachment_list_cleanup(&list);

  if (lease != NULL) {
    lease->close(lease);
  }
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_txn_recovery_applies_decisions_on_client_open(void **state) {
  static const char committed_body[] =
      "{\"category\":\"planning\",\"value\":\"recovered-commit\"}";
  static const char selector[] =
      "{\"eq\":{\"field\":\"/category\",\"value\":\"planning\"}}";
  lc_client *client;
  lc_pouch *pouch;
  lc_source *source;
  lc_pouch_state_write_result write_result;
  lc_pouch_state_read_result read_result;
  lc_query_req query_req;
  lc_query_res query_res;
  lc_query_key_handler handler;
  pouch_query_key_capture query_capture;
  lc_error error;
  char root[512];
  char bytes[128];
  int rc;

  (void)state;
  client = NULL;
  pouch = NULL;
  source = NULL;
  memset(&write_result, 0, sizeof(write_result));
  memset(&read_result, 0, sizeof(read_result));
  lc_query_req_init(&query_req);
  memset(&query_res, 0, sizeof(query_res));
  memset(&handler, 0, sizeof(handler));
  memset(&query_capture, 0, sizeof(query_capture));
  lc_error_init(&error);
  make_root("txn-recovery", root, sizeof(root));
  cleanup_root(root);

  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_source_from_memory(committed_body, strlen(committed_body), &source,
                             &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_stage_write(pouch, "orders/recover",
                                  "state/recover-commit",
                                  test_xid_for_label("txn-recover-commit"),
                                  source, NULL, &write_result, &error);
  lc_source_close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  {
    lc_txn_participant participant;

    memset(&participant, 0, sizeof(participant));
    participant.namespace_name = "orders/recover";
    participant.key = "state/recover-commit";
    participant.backend_hash = NULL;
    test_write_binary_txn_record(pouch, "txn-recover-commit", "commit", 0L, 1UL,
                                 "", &participant, 1U, &error);
  }
  rc = lc_source_from_memory("expired-stage", strlen("expired-stage"), &source,
                             &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_stage_write(pouch, "orders/recover",
                                  "state/recover-expired",
                                  test_xid_for_label("txn-recover-expired"),
                                  source, NULL, &write_result, &error);
  lc_source_close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  lc_pouch_state_write_result_cleanup(NULL, &write_result);
  {
    lc_txn_participant participant;

    memset(&participant, 0, sizeof(participant));
    participant.namespace_name = "orders/recover";
    participant.key = "state/recover-expired";
    participant.backend_hash = NULL;
    test_write_binary_txn_record(pouch, "txn-recover-expired", "prepare", 1L,
                                 1UL, "", &participant, 1U, &error);
  }
  lc_pouch_close(pouch);
  pouch = NULL;

  open_pouch_client(root, &client, &error);
  handler.begin = pouch_query_key_begin;
  handler.chunk = pouch_query_key_chunk;
  handler.end = pouch_query_key_end;
  query_req.namespace_name = "orders/recover";
  query_req.selector_json = selector;
  query_req.engine = "index";
  query_req.refresh = "wait_for";
  rc = client->query_keys(client, &query_req, &handler, &query_capture,
                          &query_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(query_capture.count, 1);
  assert_true(pouch_query_capture_has(&query_capture, "state/recover-commit"));
  assert_null(query_res.cursor);
  assert_non_null(query_res.metadata_json);
  assert_true(bytes_contain_text(query_res.metadata_json,
                                 strlen(query_res.metadata_json),
                                 "\"engine\":\"index\""));
  lc_query_res_cleanup(&query_res);

  /* The exclusive client must release the root before the raw durability probe.
   */
  lc_client_close(client);
  client = NULL;
  rc = lc_pouch_open(root, NULL, NULL, &pouch, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_pouch_state_read(pouch, "orders/recover", "state/recover-commit",
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(read_result.found);
  read_source_to_string(read_result.body, bytes, sizeof(bytes));
  assert_true(bytes_contain_text(bytes, strlen(bytes),
                                 "\"value\":\"recovered-commit\""));
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  rc = lc_pouch_state_read(pouch, "orders/recover",
                           "state/recover-expired/.staging/txn-recover-expired",
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  rc = lc_pouch_state_read(pouch, "orders/recover", "state/recover-expired",
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  rc = lc_pouch_state_read(pouch, ".txns",
                           test_xid_for_label("txn-recover-commit"),
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  rc = lc_pouch_state_read(pouch, ".txns",
                           test_xid_for_label("txn-recover-expired"),
                           &read_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(read_result.found);
  lc_pouch_state_read_result_cleanup(NULL, &read_result);
  lc_pouch_close(pouch);
  pouch = NULL;

  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void
test_lease_remove_tombstones_state_and_refreshes_view(void **state) {
  lc_client *client;
  lc_lease *lease;
  lc_source *source;
  lc_sink *sink;
  lc_acquire_req acquire_req;
  lc_get_res get_res;
  lc_error error;
  char root[512];
  char key[96];
  int rc;

  (void)state;
  client = NULL;
  lease = NULL;
  source = NULL;
  sink = NULL;
  memset(&get_res, 0, sizeof(get_res));
  lc_acquire_req_init(&acquire_req);
  lc_error_init(&error);
  make_root("lease-remove", root, sizeof(root));
  cleanup_root(root);
  snprintf(key, sizeof(key), "state/lease-remove/%ld", (long)getpid());

  open_pouch_client(root, &client, &error);
  acquire_req.key = key;
  acquire_req.owner = "lc-unit-pouch";
  acquire_req.ttl_seconds = 30L;
  rc = client->acquire(client, &acquire_req, &lease, &error);
  assert_int_equal(rc, LC_OK);
  rc = lc_source_from_memory("{\"value\":12}", strlen("{\"value\":12}"),
                             &source, &error);
  assert_int_equal(rc, LC_OK);
  rc = lease->update(lease, source, NULL, &error);
  source->close(source);
  source = NULL;
  assert_int_equal(rc, LC_OK);
  assert_int_equal(lease->version, 1L);
  assert_non_null(lease->state_etag);

  rc = lease->remove(lease, NULL, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(lease->version, 0L);
  assert_null(lease->state_etag);

  rc = lc_sink_to_memory(&sink, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->get(client, key, NULL, sink, &get_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_true(get_res.no_content);
  sink->close(sink);

  lc_get_res_cleanup(&get_res);
  lease->close(lease);
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void test_acquire_for_update_success_and_rollback(void **state) {
  lc_client *client;
  lc_sink *sink;
  lc_update_res update_res;
  lc_get_res get_res;
  lc_acquire_req acquire_req;
  lc_error error;
  pouch_acquire_for_update_state handler_state;
  const void *bytes;
  size_t length;
  char root[512];
  char key[96];
  int rc;

  (void)state;
  client = NULL;
  sink = NULL;
  bytes = NULL;
  length = 0U;
  memset(&update_res, 0, sizeof(update_res));
  memset(&get_res, 0, sizeof(get_res));
  lc_acquire_req_init(&acquire_req);
  lc_error_init(&error);
  make_root("acquire-for-update", root, sizeof(root));
  cleanup_root(root);
  snprintf(key, sizeof(key), "state/afu/%ld", (long)getpid());

  open_pouch_client(root, &client, &error);
  write_client_state(client, key, "{\"value\":1}", NULL, 0L, 0, &update_res,
                     &error);
  lc_update_res_cleanup(&update_res);

  memset(&handler_state, 0, sizeof(handler_state));
  handler_state.expected_snapshot = "\"value\":1";
  handler_state.expected_visible_during_update = "{\"value\":1}";
  handler_state.replacement = "{\"value\":2}";
  handler_state.observer = client;
  handler_state.key = key;
  acquire_req.key = key;
  acquire_req.owner = "lc-unit-pouch";
  acquire_req.ttl_seconds = 30L;
  rc = client->acquire_for_update(client, &acquire_req,
                                  pouch_acquire_for_update_handler,
                                  &handler_state, &error);
  if (rc != LC_OK) {
    fail_msg("acquire_for_update failed: %s",
             error.message != NULL ? error.message : "(no message)");
  }
  assert_int_equal(rc, LC_OK);
  assert_int_equal(handler_state.saw_snapshot, 1);
  assert_int_equal(handler_state.saw_staged_invisible, 1);
  assert_int_equal(handler_state.saw_staging_key_rejected, 1);

  rc = lc_sink_to_memory(&sink, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->get(client, key, NULL, sink, &get_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(get_res.no_content);
  rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(length, strlen("{\"value\":2}"));
  assert_memory_equal(bytes, "{\"value\":2}", strlen("{\"value\":2}"));
  sink->close(sink);
  sink = NULL;
  lc_get_res_cleanup(&get_res);

  lc_error_cleanup(&error);
  lc_error_init(&error);
  memset(&handler_state, 0, sizeof(handler_state));
  handler_state.expected_snapshot = "\"value\":2";
  handler_state.expected_visible_during_update = "{\"value\":2}";
  handler_state.replacement = "{\"value\":3}";
  handler_state.observer = client;
  handler_state.key = key;
  handler_state.fail = 1;
  rc = client->acquire_for_update(client, &acquire_req,
                                  pouch_acquire_for_update_handler,
                                  &handler_state, &error);
  assert_int_equal(rc, LC_ERR_INVALID);
  assert_string_equal(error.message,
                      "intentional pouch acquire_for_update failure");
  assert_int_equal(handler_state.saw_staged_invisible, 1);
  assert_int_equal(handler_state.saw_staging_key_rejected, 1);

  lc_error_cleanup(&error);
  lc_error_init(&error);
  memset(&get_res, 0, sizeof(get_res));
  rc = lc_sink_to_memory(&sink, &error);
  assert_int_equal(rc, LC_OK);
  rc = client->get(client, key, NULL, sink, &get_res, &error);
  assert_int_equal(rc, LC_OK);
  assert_false(get_res.no_content);
  rc = lc_sink_memory_bytes(sink, &bytes, &length, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(length, strlen("{\"value\":2}"));
  assert_memory_equal(bytes, "{\"value\":2}", strlen("{\"value\":2}"));
  sink->close(sink);

  lc_get_res_cleanup(&get_res);
  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

static void
test_exclusive_indexer_retires_expired_acquire_for_update_guard(void **state) {
  lc_client *client;
  lc_client_handle *handle;
  lc_acquire_req acquire_req;
  lc_pouch_generation manifest_seq;
  lc_pouch_generation query_seq;
  lc_pouch_query_index_flush_result flush_result;
  lc_error error;
  pouch_acquire_for_update_state handler_state;
  char endpoint[1024];
  char root[512];
  int rc;

  (void)state;
  client = NULL;
  manifest_seq = 0UL;
  query_seq = 0UL;
  lc_acquire_req_init(&acquire_req);
  memset(&handler_state, 0, sizeof(handler_state));
  memset(&flush_result, 0, sizeof(flush_result));
  lc_error_init(&error);
  make_root("indexer-expired-acquire-for-update-guard", root, sizeof(root));
  cleanup_root(root);
  assert_true(snprintf(endpoint, sizeof(endpoint),
                       "pouch://%s?indexer_flush_docs=1&"
                       "indexer_flush_interval_seconds=3600",
                       root) > 0);

  open_pouch_client_endpoint(endpoint, &client, &error);
  handle = (lc_client_handle *)client;
  handler_state.replacement = "{\"kind\":\"late\"}";
  handler_state.delay_seconds = 2U;
  acquire_req.key = "doc/expired-acquire-for-update";
  acquire_req.owner = "pouch-indexer-expired-acquire-for-update";
  acquire_req.ttl_seconds = 1L;
  rc = client->acquire_for_update(client, &acquire_req,
                                  pouch_acquire_for_update_handler,
                                  &handler_state, &error);
  assert_int_equal(rc, LC_ERR_INVALID);

  /* Promotion is durable, but the expired release cannot signal completion.
   * Its lease-scoped guard must retire instead of deferring this namespace
   * until the client closes. */
  lc_error_cleanup(&error);
  lc_error_init(&error);
  rc = lc_pouch_state_query_index_seq(handle->pouch, "default", &query_seq,
                                      &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(query_seq, 0UL);
  rc = lc_pouch_query_index_flush_threshold(handle->pouch, "default", query_seq,
                                            &flush_result, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(flush_result.index_seq, 0UL);
  rc = lc_pouch_query_index_manifest_seq(handle->pouch, "default",
                                         &manifest_seq, &error);
  assert_int_equal(rc, LC_OK);
  assert_int_equal(manifest_seq, query_seq);
  assert_false(lc_pouch_query_index_has_pending(handle->pouch, "default"));

  lc_client_close(client);
  cleanup_root(root);
  lc_error_cleanup(&error);
}

